const CONTENT_PACKS = [{"id":"2026-09-27-initial-batch","released":"2026-09-27","kind":"initial","reading_passages":{"0":[{"text":"Kai has a blue bucket. He fills it with sand at the beach. Then he builds a big castle.","questions":[{"question":"What color is the bucket?","choices":["blue","red","green","yellow"],"answer":"blue"},{"question":"Where is Kai?","choices":["at the beach","at school","at home","at the zoo"],"answer":"at the beach"},{"question":"What does Kai build?","choices":["a castle","a boat","a house","a tower"],"answer":"a castle"}]},{"text":"Ruby has a little frog. The frog is green. It hops on a log by the pond.","questions":[{"question":"What color is the frog?","choices":["green","red","brown","pink"],"answer":"green"},{"question":"Where does the frog hop?","choices":["on a log","in a box","on a bed","on a bus"],"answer":"on a log"}]},{"text":"Owen likes to eat soup. Today the soup is hot. He blows on it to cool it down.","questions":[{"question":"What does Owen eat?","choices":["soup","pizza","cake","corn"],"answer":"soup"},{"question":"How is the soup?","choices":["hot","cold","sweet","green"],"answer":"hot"},{"question":"What does Owen do to cool it?","choices":["blows on it","adds ice","waits a day","drinks it fast"],"answer":"blows on it"}]},{"text":"The bus is yellow. It stops at the school. Many kids get on the bus.","questions":[{"question":"What color is the bus?","choices":["yellow","blue","red","black"],"answer":"yellow"},{"question":"Where does the bus stop?","choices":["at the school","at the park","at the zoo","at the farm"],"answer":"at the school"}]},{"text":"Zoe plants a seed in a pot. She gives it water and sun. A small green plant grows.","questions":[{"question":"What does Zoe plant?","choices":["a seed","a rock","a toy","a shoe"],"answer":"a seed"},{"question":"What grows?","choices":["a small green plant","a big tree","a red flower","a bug"],"answer":"a small green plant"}]},{"text":"Max has a red kite. The wind is strong today. The kite flies high in the sky.","questions":[{"question":"What color is the kite?","choices":["red","blue","green","white"],"answer":"red"},{"question":"What is strong today?","choices":["the wind","the rain","the sun","the dog"],"answer":"the wind"},{"question":"Where does the kite fly?","choices":["high in the sky","under a tree","in a box","on the floor"],"answer":"high in the sky"}]},{"text":"Nina bakes a cake with her mom. The cake is pink. They put it on the table.","questions":[{"question":"Who bakes with Nina?","choices":["her mom","her dad","her friend","her dog"],"answer":"her mom"},{"question":"What color is the cake?","choices":["pink","brown","blue","white"],"answer":"pink"}]},{"text":"A duck swims in the pond. Her ducklings swim behind her. They all say quack.","questions":[{"question":"Who swims behind the duck?","choices":["her ducklings","her cats","her frogs","her fish"],"answer":"her ducklings"},{"question":"What do they say?","choices":["quack","moo","woof","meow"],"answer":"quack"}]},{"text":"Leo puts on his coat and hat. It is cold outside. He goes out to play in the snow.","questions":[{"question":"How is the weather?","choices":["cold","hot","warm","sunny"],"answer":"cold"},{"question":"Where does Leo play?","choices":["in the snow","in the sand","in a pool","in the mud"],"answer":"in the snow"}]},{"text":"Ava has a soft bed. At night she reads a book. Then she turns off the light and sleeps.","questions":[{"question":"What does Ava read?","choices":["a book","a map","a note","a sign"],"answer":"a book"},{"question":"What does she turn off?","choices":["the light","the radio","the fan","the tap"],"answer":"the light"}]},{"text":"The cow lives on a farm. She gives us milk. The farmer feeds her hay.","questions":[{"question":"Where does the cow live?","choices":["on a farm","in a pond","in a zoo","in a shop"],"answer":"on a farm"},{"question":"What does the cow give us?","choices":["milk","eggs","wool","honey"],"answer":"milk"},{"question":"What does the farmer feed her?","choices":["hay","fish","cake","rice"],"answer":"hay"}]},{"text":"Ben has four blocks. He stacks them up. The tower is tall.","questions":[{"question":"How many blocks does Ben have?","choices":["four","two","five","six"],"answer":"four"},{"question":"What does Ben do with the blocks?","choices":["stacks them up","throws them","hides them","paints them"],"answer":"stacks them up"}]},{"text":"Ivy sees a bee on a flower. The bee is yellow and black. It buzzes and flies away.","questions":[{"question":"Where is the bee?","choices":["on a flower","on a chair","on a cup","on a bike"],"answer":"on a flower"},{"question":"What sound does the bee make?","choices":["buzz","quack","roar","moo"],"answer":"buzz"}]},{"text":"Sam is sad. His ice cream fell on the ground. His mom gives him a new one.","questions":[{"question":"Why is Sam sad?","choices":["his ice cream fell","he lost a shoe","it is raining","he is tired"],"answer":"his ice cream fell"},{"question":"Who gives him a new one?","choices":["his mom","his dad","his friend","his teacher"],"answer":"his mom"}]},{"text":"Lily has a puppy. The puppy likes to dig in the garden. Lily gives it a bath.","questions":[{"question":"What does the puppy like to do?","choices":["dig","swim","sing","climb"],"answer":"dig"},{"question":"What does Lily give the puppy?","choices":["a bath","a toy","a hat","a bone"],"answer":"a bath"}]},{"text":"We go to the park on Sunday. We play on the swings. Then we eat a picnic.","questions":[{"question":"When do we go to the park?","choices":["Sunday","Monday","Friday","Tuesday"],"answer":"Sunday"},{"question":"What do we play on?","choices":["the swings","the slide","the bus","the boat"],"answer":"the swings"},{"question":"What do we eat?","choices":["a picnic","a pie","a pizza","a soup"],"answer":"a picnic"}]},{"text":"Theo has a toy train. It has three red cars. It goes around and around on the track.","questions":[{"question":"How many red cars does it have?","choices":["three","one","four","five"],"answer":"three"},{"question":"Where does the train go?","choices":["on the track","on the road","in the sea","up the tree"],"answer":"on the track"}]},{"text":"The moon is bright tonight. Stars twinkle in the dark sky. Mia looks at them from her window.","questions":[{"question":"When is the moon bright?","choices":["tonight","at noon","this morning","at lunch"],"answer":"tonight"},{"question":"What twinkles in the sky?","choices":["stars","cars","birds","fish"],"answer":"stars"},{"question":"Where does Mia look from?","choices":["her window","her car","her boat","her desk"],"answer":"her window"}]},{"text":"Jack drinks water from a cup. He is thirsty. He drinks it all up.","questions":[{"question":"What does Jack drink?","choices":["water","milk","juice","soup"],"answer":"water"},{"question":"How does Jack feel?","choices":["thirsty","sleepy","cold","sad"],"answer":"thirsty"}]},{"text":"The hen lays an egg. The egg is white. The farmer takes it to the kitchen.","questions":[{"question":"What does the hen lay?","choices":["an egg","a nut","a stone","a ball"],"answer":"an egg"},{"question":"What color is the egg?","choices":["white","brown","blue","pink"],"answer":"white"},{"question":"Who takes it to the kitchen?","choices":["the farmer","the cook","the baker","the dog"],"answer":"the farmer"}]},{"text":"Hana wears red boots in the rain. She jumps in a puddle. Splash! Water goes everywhere.","questions":[{"question":"What does Hana wear?","choices":["red boots","blue shoes","a green coat","a big hat"],"answer":"red boots"},{"question":"What does she jump in?","choices":["a puddle","a box","a bed","a bag"],"answer":"a puddle"}]},{"text":"Eli has a drum. He hits it with two sticks. Boom, boom, boom!","questions":[{"question":"What does Eli have?","choices":["a drum","a horn","a bell","a flute"],"answer":"a drum"},{"question":"What does he hit it with?","choices":["two sticks","his hands","a spoon","a shoe"],"answer":"two sticks"}]},{"text":"The fish is orange. It swims in a bowl. Chloe feeds it every morning.","questions":[{"question":"What color is the fish?","choices":["orange","blue","black","purple"],"answer":"orange"},{"question":"Where does the fish swim?","choices":["in a bowl","in a lake","in a cup","in a sink"],"answer":"in a bowl"},{"question":"When does Chloe feed it?","choices":["every morning","at night","at noon","on Sunday"],"answer":"every morning"}]},{"text":"Omar and his dad make a snowman. It has a carrot nose and two black eyes. They put a scarf on it.","questions":[{"question":"What nose does the snowman have?","choices":["a carrot nose","a red nose","a big nose","no nose"],"answer":"a carrot nose"},{"question":"What do they put on it?","choices":["a scarf","a coat","a bag","a shoe"],"answer":"a scarf"}]}],"1":[{"text":"Penguins cannot fly, but they are excellent swimmers. Their wings work like flippers, pushing them quickly through the water. Penguins spend most of their day hunting for fish in the cold sea.","questions":[{"question":"What do penguins use their wings for?","choices":["swimming","flying","digging","climbing"],"answer":"swimming"},{"question":"What do penguins hunt?","choices":["fish","birds","insects","seals"],"answer":"fish"},{"question":"Why can penguins move fast in water?","choices":["their wings work like flippers","they have long legs","they are very small","the water is warm"],"answer":"their wings work like flippers"}]},{"text":"Marcus wanted to bake bread, so he mixed flour, water, and yeast. He left the dough near the window for an hour. When he came back, the dough had grown twice as big. Then he baked it until it was golden.","questions":[{"question":"What did Marcus mix?","choices":["flour, water, and yeast","sugar, eggs, and milk","butter and salt","rice and beans"],"answer":"flour, water, and yeast"},{"question":"What happened to the dough?","choices":["it grew twice as big","it turned blue","it disappeared","it got smaller"],"answer":"it grew twice as big"},{"question":"Where did he leave the dough?","choices":["near the window","in the fridge","on the stove","in the sink"],"answer":"near the window"}]},{"text":"The library is a quiet place. People read books, use computers, and do homework there. The librarian helps visitors find the right book. Kids can borrow up to five books at a time.","questions":[{"question":"Who helps visitors find books?","choices":["the librarian","the teacher","the baker","the driver"],"answer":"the librarian"},{"question":"How many books can kids borrow?","choices":["five","two","ten","three"],"answer":"five"}]},{"text":"Amara's class went on a walk to collect leaves. They found red, orange, and yellow ones. Back at school, they pressed the leaves inside heavy books. After a week, the leaves were flat and dry.","questions":[{"question":"What colors of leaves did they find?","choices":["red, orange, and yellow","blue, pink, and white","black and gray","purple and silver"],"answer":"red, orange, and yellow"},{"question":"What did they press the leaves inside?","choices":["heavy books","wet towels","small boxes","warm ovens"],"answer":"heavy books"},{"question":"How long did it take for the leaves to dry?","choices":["a week","a day","a month","a year"],"answer":"a week"}]},{"text":"Bees live together in a hive. Worker bees fly out to find flowers and bring back nectar. Inside the hive, the bees turn the nectar into honey. One hive can make enough honey to feed many families.","questions":[{"question":"What do worker bees bring back?","choices":["nectar","seeds","leaves","water"],"answer":"nectar"},{"question":"What do bees make from nectar?","choices":["honey","wax","milk","sand"],"answer":"honey"},{"question":"Where do bees live?","choices":["in a hive","in a nest","in a burrow","in a cave"],"answer":"in a hive"}]},{"text":"Diego was nervous about his first swimming lesson. The water looked very deep. His teacher showed him how to float on his back. Soon Diego was smiling because floating felt easy.","questions":[{"question":"Why was Diego nervous?","choices":["it was his first lesson","he forgot his towel","the water was hot","he lost his goggles"],"answer":"it was his first lesson"},{"question":"What did the teacher show him?","choices":["how to float","how to dive","how to race","how to sing"],"answer":"how to float"}]},{"text":"A rainbow appears when sunlight shines through raindrops. The light bends and splits into many colors. A rainbow has red, orange, yellow, green, blue, and violet. You can often see one after a rain shower when the sun comes out.","questions":[{"question":"When does a rainbow appear?","choices":["when sunlight shines through raindrops","when it is very cold","when snow falls","at midnight"],"answer":"when sunlight shines through raindrops"},{"question":"How many colors does the passage name?","choices":["six","four","five","eight"],"answer":"six"},{"question":"When can you often see a rainbow?","choices":["after a rain shower","before a storm","in a dark room","during the night"],"answer":"after a rain shower"}]},{"text":"Rosa helps her grandmother in the garden every Saturday. They plant tomatoes, carrots, and beans. Rosa waters the plants with a small can. In summer, they pick the vegetables and cook a big dinner.","questions":[{"question":"When does Rosa help in the garden?","choices":["every Saturday","every Monday","every night","every winter"],"answer":"every Saturday"},{"question":"What does Rosa water the plants with?","choices":["a small can","a big hose","a bucket","a cup"],"answer":"a small can"},{"question":"What do they do in summer?","choices":["pick the vegetables","sell the house","go on a trip","paint the fence"],"answer":"pick the vegetables"}]},{"text":"Camels can go many days without water. They store fat in their humps, not water. This fat gives them energy when food is hard to find. Their wide feet also keep them from sinking in soft sand.","questions":[{"question":"What do camels store in their humps?","choices":["fat","water","sand","milk"],"answer":"fat"},{"question":"What do wide feet help camels do?","choices":["not sink in sand","swim fast","climb trees","stay cold"],"answer":"not sink in sand"},{"question":"What does the stored fat give camels?","choices":["energy","shade","noise","color"],"answer":"energy"}]},{"text":"Every night before bed, Jamal brushes his teeth for two minutes. He uses a soft brush and a little toothpaste. His dentist says this keeps teeth strong and healthy. Jamal has never had a cavity.","questions":[{"question":"How long does Jamal brush his teeth?","choices":["two minutes","ten minutes","one hour","five seconds"],"answer":"two minutes"},{"question":"Who says brushing keeps teeth healthy?","choices":["his dentist","his coach","his uncle","his neighbor"],"answer":"his dentist"},{"question":"What has Jamal never had?","choices":["a cavity","a haircut","a cold","a sticker"],"answer":"a cavity"}]},{"text":"The town holds a lemonade stand day each summer. Kids set up tables and sell cold drinks to neighbors. Priya made her lemonade with fresh lemons and a little honey. She sold every cup before noon.","questions":[{"question":"When does the town hold the event?","choices":["each summer","each winter","each spring","every night"],"answer":"each summer"},{"question":"What did Priya use in her lemonade?","choices":["fresh lemons and a little honey","orange juice and salt","sugar and milk","apples and mint"],"answer":"fresh lemons and a little honey"},{"question":"When did Priya sell every cup?","choices":["before noon","after dark","at midnight","the next day"],"answer":"before noon"}]},{"text":"Sea turtles hatch from eggs buried in warm sand. After hatching, the tiny turtles crawl toward the ocean. Many are eaten by birds on the way. Only a few survive to become adults.","questions":[{"question":"Where are sea turtle eggs buried?","choices":["in warm sand","in cold mud","under rocks","in tall grass"],"answer":"in warm sand"},{"question":"Where do the hatchlings crawl?","choices":["toward the ocean","into the forest","up a tree","into a cave"],"answer":"toward the ocean"},{"question":"Why do only a few survive?","choices":["many are eaten by birds","the water is too cold","they cannot swim","they forget the way"],"answer":"many are eaten by birds"}]},{"text":"On rainy days, Theo's family plays board games. Tonight they are playing checkers. Theo's sister always tries to win, but Theo likes just having fun. He laughs when she makes silly moves.","questions":[{"question":"What game are they playing tonight?","choices":["checkers","chess","cards","tag"],"answer":"checkers"},{"question":"Who always tries to win?","choices":["Theo's sister","Theo's dad","Theo's mom","the dog"],"answer":"Theo's sister"},{"question":"What does Theo like?","choices":["having fun","winning","sleeping","reading"],"answer":"having fun"}]},{"text":"The moon does not make its own light. It shines because it reflects light from the sun. As the moon travels around Earth, we see different parts of it lit up. This is why the moon seems to change shape each night.","questions":[{"question":"Where does the moon's light come from?","choices":["the sun","a lamp","the stars","the ocean"],"answer":"the sun"},{"question":"What does the moon travel around?","choices":["Earth","Mars","the sun","Venus"],"answer":"Earth"},{"question":"Why does the moon seem to change shape?","choices":["we see different parts lit up","clouds cover it","it melts","it grows and shrinks"],"answer":"we see different parts lit up"}]},{"text":"Chloe lost her lunch box on the bus. She looked in her bag and under her seat, but it was gone. The next morning, the bus driver returned it. Chloe thanked him with a big smile.","questions":[{"question":"Where did Chloe lose her lunch box?","choices":["on the bus","at the park","in the gym","at home"],"answer":"on the bus"},{"question":"Who returned it?","choices":["the bus driver","her teacher","her friend","her mom"],"answer":"the bus driver"},{"question":"How did Chloe thank him?","choices":["with a big smile","with a gift","with a song","with a card"],"answer":"with a big smile"}]},{"text":"Ice cream melts quickly on a hot day. The warm air turns the frozen treat into a sticky puddle. To stop this, Ravi eats his cone fast and holds a napkin. He finishes before a single drop falls.","questions":[{"question":"What makes ice cream melt?","choices":["warm air","cold wind","loud noise","dark clouds"],"answer":"warm air"},{"question":"What does Ravi hold?","choices":["a napkin","a spoon","a plate","a cup"],"answer":"a napkin"}]},{"text":"The school garden has a scarecrow. It wears an old hat and a checked shirt. Its job is to keep birds away from the seeds. The students named it Mr. Straw.","questions":[{"question":"What does the scarecrow wear?","choices":["an old hat and a checked shirt","a red coat and boots","a crown and a cape","a blue dress"],"answer":"an old hat and a checked shirt"},{"question":"What is the scarecrow's job?","choices":["keep birds away","water the plants","dig the soil","sing songs"],"answer":"keep birds away"},{"question":"What did the students name it?","choices":["Mr. Straw","Farmer Joe","Old Hat","Big Bird"],"answer":"Mr. Straw"}]},{"text":"Mountains are formed when huge pieces of Earth's crust push against each other. Over millions of years, the land is pushed upward. Wind and rain slowly wear the peaks down. This is why very old mountains look rounder than young ones.","questions":[{"question":"How are mountains formed?","choices":["pieces of crust push together","rivers dry up","volcanoes sleep","wind builds them fast"],"answer":"pieces of crust push together"},{"question":"What slowly wears peaks down?","choices":["wind and rain","snow only","sunlight","animals"],"answer":"wind and rain"},{"question":"Which mountains look rounder?","choices":["very old ones","young ones","tall trees","small hills"],"answer":"very old ones"}]},{"text":"Elena practices the piano after school. She plays scales first to warm up her fingers. Then she learns a new song, one small part at a time. When she plays the whole song without mistakes, she puts a star on her chart.","questions":[{"question":"What does Elena play first?","choices":["scales","a new song","her favorite song","a duet"],"answer":"scales"},{"question":"How does she learn a new song?","choices":["one small part at a time","all at once","by watching TV","with no practice"],"answer":"one small part at a time"},{"question":"What does she put on her chart?","choices":["a star","a heart","a flag","a number"],"answer":"a star"}]},{"text":"Frogs begin life as eggs in the water. The eggs hatch into tadpoles, which have tails and gills. Slowly, the tadpoles grow legs and lose their tails. Finally, they become frogs that can live on land.","questions":[{"question":"What do tadpoles have?","choices":["tails and gills","wings and fur","shells and claws","feathers and beaks"],"answer":"tails and gills"},{"question":"What do tadpoles slowly grow?","choices":["legs","wings","horns","feathers"],"answer":"legs"},{"question":"Where can adult frogs live?","choices":["on land","only in trees","only in caves","only in ice"],"answer":"on land"}]},{"text":"The bakery on Main Street opens at six every morning. Mr. Lopez bakes fresh rolls and muffins before the sun comes up. Neighbors line up to buy warm bread. By eight, the shelves are almost empty.","questions":[{"question":"When does the bakery open?","choices":["six every morning","noon","midnight","four in the afternoon"],"answer":"six every morning"},{"question":"Who bakes the rolls and muffins?","choices":["Mr. Lopez","Mr. Stone","Ms. Rivera","Mr. Kim"],"answer":"Mr. Lopez"},{"question":"What is almost empty by eight?","choices":["the shelves","the ovens","the street","the cash box"],"answer":"the shelves"}]},{"text":"A thunderstorm starts with warm air rising quickly. The air cools and forms tall dark clouds. Lightning is a giant spark of electricity in the cloud. Thunder is the loud sound the lightning makes.","questions":[{"question":"What is lightning?","choices":["a giant spark of electricity","a kind of rain","a loud sound","a type of wind"],"answer":"a giant spark of electricity"},{"question":"What is thunder?","choices":["the loud sound lightning makes","a bright flash","a type of cloud","a cold breeze"],"answer":"the loud sound lightning makes"}]},{"text":"Nora's little brother is learning to walk. He holds the couch and takes a tiny step. Then he wobbles and sits down with a thump. Everyone claps, and he tries again.","questions":[{"question":"What is Nora's brother learning?","choices":["to walk","to swim","to read","to draw"],"answer":"to walk"},{"question":"What does he hold?","choices":["the couch","the door","a toy","a hand"],"answer":"the couch"},{"question":"What does everyone do?","choices":["clap","cry","leave","sleep"],"answer":"clap"}]},{"text":"The ant carried a crumb twice its size across the yard. It walked around a rock and over a twig. Other ants joined to help pull the crumb. Together, they carried it into their nest.","questions":[{"question":"What did the ant carry?","choices":["a crumb","a leaf","a seed","a stick"],"answer":"a crumb"},{"question":"What did the other ants do?","choices":["helped pull the crumb","ran away","ate the crumb","hid under a rock"],"answer":"helped pull the crumb"},{"question":"Where did they take it?","choices":["into their nest","into the pond","up a tree","under the house"],"answer":"into their nest"}]}],"2":[{"text":"Engineers design suspension bridges to span wide rivers and deep valleys. Thick steel cables hang between tall towers, and smaller vertical cables connect the road to the main cables. The design spreads the weight of traffic across the whole structure, so no single part carries too much. Because the road can flex slightly in the wind, suspension bridges can be longer than most other kinds.","questions":[{"question":"What holds the road up on a suspension bridge?","choices":["vertical cables joined to the main cables","giant wooden beams below","floating platforms","heavy stone arches"],"answer":"vertical cables joined to the main cables"},{"question":"Why can suspension bridges be so long?","choices":["the road can flex slightly in the wind","they are made of stone","they use no steel","they are built on ice"],"answer":"the road can flex slightly in the wind"},{"question":"In the passage, the word span means?","choices":["to stretch across","to break apart","to paint over","to dig under"],"answer":"to stretch across"}]},{"text":"Plants make their own food through a process called photosynthesis. Their leaves absorb sunlight, take in carbon dioxide from the air, and draw up water through the roots. Using the energy of light, the plant turns these ingredients into sugar and releases oxygen. Animals, including people, depend on that oxygen to breathe, which makes plants essential to nearly all life on Earth.","questions":[{"question":"What do plants release during photosynthesis?","choices":["oxygen","carbon dioxide","nitrogen","smoke"],"answer":"oxygen"},{"question":"Why are plants essential to animals?","choices":["they release oxygen animals breathe","they give off heat at night","they stop the wind","they attract the rain"],"answer":"they release oxygen animals breathe"},{"question":"What does the plant make from light, water, and carbon dioxide?","choices":["sugar","salt","oil","soap"],"answer":"sugar"}]},{"text":"The ancient Egyptians built pyramids as tombs for their pharaohs. Thousands of workers cut enormous blocks of limestone and dragged them on wooden sledges to the building site. The Great Pyramid of Giza, completed around 2560 BCE, was the tallest structure on Earth for nearly four thousand years. Inside, chambers held treasures the Egyptians believed a pharaoh would need in the afterlife.","questions":[{"question":"Why did Egyptians build pyramids?","choices":["as tombs for their pharaohs","as homes for workers","as markets","as lighthouses"],"answer":"as tombs for their pharaohs"},{"question":"How did workers move the heavy blocks?","choices":["on wooden sledges","with steam engines","on boats only","using giant wheels"],"answer":"on wooden sledges"},{"question":"What can you infer about the Egyptians' beliefs?","choices":["they believed in an afterlife","they feared the sun","they had no religion","they never built anything else"],"answer":"they believed in an afterlife"}]},{"text":"Ocean tides rise and fall because of the moon's gravity. The moon pulls on Earth's water, creating a bulge on the side facing the moon. A second bulge forms on the opposite side of Earth. As the planet rotates, coastlines move through these bulges, which is why most places experience two high tides and two low tides every day. The sun also pulls on the oceans, but its effect is smaller.","questions":[{"question":"What mainly causes ocean tides?","choices":["the moon's gravity","ocean winds","underwater volcanoes","the sun's heat"],"answer":"the moon's gravity"},{"question":"How many high tides do most coastlines get each day?","choices":["two","one","three","four"],"answer":"two"},{"question":"Why is the sun's effect on tides smaller?","choices":["it is much farther away","it is smaller than Earth","it does not have gravity","its light is too weak"],"answer":"it is much farther away"}]},{"text":"Marie Curie was a physicist and chemist who studied radioactivity in the early 1900s. She discovered two new elements, polonium and radium, and became the first person to win Nobel Prizes in two different sciences. Her work laid the foundation for modern cancer treatments. During World War I, she also developed mobile X-ray units that doctors used near the battlefield to help wounded soldiers.","questions":[{"question":"What did Marie Curie study?","choices":["radioactivity","volcanoes","plants","sound waves"],"answer":"radioactivity"},{"question":"What was special about her Nobel Prizes?","choices":["she won in two different sciences","she won three in one year","she won them as a child","she gave them all away"],"answer":"she won in two different sciences"},{"question":"In the passage, the word foundation means?","choices":["a base for later work","a type of building","a small prize","a kind of experiment"],"answer":"a base for later work"}]},{"text":"Honeybees communicate with a remarkable waggle dance. When a bee finds good flowers, it returns to the hive and moves in a figure-eight pattern. The angle of the dance shows the direction of the flowers relative to the sun, and the length of the waggle shows the distance. Other bees watch closely, then fly straight to the food. This teamwork helps the whole colony gather nectar efficiently.","questions":[{"question":"What does the angle of the dance show?","choices":["the direction of the flowers","the type of flower","the time of day","the number of bees"],"answer":"the direction of the flowers"},{"question":"What does the length of the waggle show?","choices":["the distance to the flowers","the weather outside","the size of the hive","the color of the nectar"],"answer":"the distance to the flowers"},{"question":"What is the main idea of the passage?","choices":["bees share food locations by dancing","bees dislike the sun","bees build figure eights","bees only work alone"],"answer":"bees share food locations by dancing"}]},{"text":"A glacier is a huge river of ice that moves very slowly across land. Glaciers form where more snow falls each year than melts. Over centuries, the snow is squeezed into dense ice. As a glacier creeps downhill, it carves deep valleys and carries rocks along with it. Today, many glaciers are shrinking because temperatures are rising, which adds water to the oceans.","questions":[{"question":"Where do glaciers form?","choices":["where more snow falls than melts","where rivers dry out","near hot deserts","where the ground is flat and warm"],"answer":"where more snow falls than melts"},{"question":"What do moving glaciers do to the land?","choices":["carve deep valleys","build tall mountains overnight","stop all rainfall","create new deserts"],"answer":"carve deep valleys"},{"question":"Why are many glaciers shrinking?","choices":["temperatures are rising","more snow is falling","rivers are pulling them","the moon is closer"],"answer":"temperatures are rising"}]},{"text":"The kangaroo rat survives in the desert without ever drinking water. It gets moisture from the seeds it eats and produces very little waste, so its body loses almost no water. During the scorching day, it stays in a cool underground burrow and comes out only at night to search for food. These adaptations allow the tiny rodent to thrive where most animals could not.","questions":[{"question":"How does the kangaroo rat get moisture?","choices":["from the seeds it eats","from morning dew","from puddles","from other animals"],"answer":"from the seeds it eats"},{"question":"Why does it stay underground during the day?","choices":["to avoid the scorching heat","to hide from plants","to sleep in the sun","to dig for water"],"answer":"to avoid the scorching heat"},{"question":"In the passage, the word adaptations means?","choices":["changes that help survival","fast movements","loud sounds","large groups"],"answer":"changes that help survival"}]},{"text":"Alexander Graham Bell patented the telephone in 1876. His invention converted the sound of a voice into electrical signals that traveled along a wire, then turned them back into sound at the other end. At first, many people doubted that anyone would want such a device. Within a few decades, however, telephone lines connected cities across the country and changed how people did business and stayed in touch.","questions":[{"question":"What did Bell's telephone do?","choices":["turned voices into electrical signals","sent written letters","recorded music","measured distance"],"answer":"turned voices into electrical signals"},{"question":"How did people first react to the telephone?","choices":["many doubted it would be useful","everyone bought one","they thought it was dangerous","they ignored it for centuries"],"answer":"many doubted it would be useful"},{"question":"What is the main idea of the passage?","choices":["the telephone changed how people communicate","Bell disliked his invention","wires are hard to make","cities grew in the 1800s"],"answer":"the telephone changed how people communicate"}]},{"text":"Every fall, millions of monarch butterflies travel up to three thousand miles from Canada and the United States to forests in Mexico. No single butterfly makes the whole round trip. Instead, it takes several generations to complete the cycle, yet the newest generation somehow finds the same mountain forests its great-grandparents left. Scientists are still studying how the butterflies navigate such a long distance.","questions":[{"question":"Where do monarchs spend the winter?","choices":["forests in Mexico","deserts in Africa","icy fields in Canada","cities in Europe"],"answer":"forests in Mexico"},{"question":"Why is the migration surprising?","choices":["new generations find the same forests","the butterflies travel at night only","they never stop flying","they follow a single leader"],"answer":"new generations find the same forests"},{"question":"What can you infer about scientists?","choices":["they do not fully understand it yet","they have solved every mystery","they ignore butterflies","they disagree the trip is real"],"answer":"they do not fully understand it yet"}]},{"text":"Sound travels as vibrations that move through air, water, and solid objects. When a guitar string is plucked, it vibrates and pushes on the air around it, creating waves that reach your ears. Sound moves fastest through solids and slowest through gases, which is why you can hear a train coming by putting your ear against the track. In outer space, where there is almost no air, sound cannot travel at all.","questions":[{"question":"What creates sound?","choices":["vibrations","magnets","sunlight","cold air"],"answer":"vibrations"},{"question":"Through which material does sound travel fastest?","choices":["solids","gases","empty space","clouds"],"answer":"solids"},{"question":"Why can't sound travel in outer space?","choices":["there is almost no air","it is too dark","it is too far","there is too much light"],"answer":"there is almost no air"}]},{"text":"For centuries, the Silk Road connected China with the Mediterranean world. Merchants did not travel the entire route themselves; goods passed from trader to trader across deserts and mountains. Silk, spices, and paper moved west, while gold, glass, and horses moved east. Just as importantly, ideas, religions, and inventions spread along the same paths, linking cultures that might otherwise never have met.","questions":[{"question":"What moved west along the Silk Road?","choices":["silk, spices, and paper","gold and glass only","horses only","no goods at all"],"answer":"silk, spices, and paper"},{"question":"How did goods usually travel the route?","choices":["passing from trader to trader","one merchant made the whole trip","by airplane","on a single ship"],"answer":"passing from trader to trader"},{"question":"What else spread along the Silk Road?","choices":["ideas and inventions","only food","only animals","only money"],"answer":"ideas and inventions"}]},{"text":"Seasons happen because Earth's axis is tilted as it orbits the sun. When the northern half of Earth tilts toward the sun, it receives more direct sunlight and longer days, creating summer. Six months later, that half tilts away, so sunlight is weaker and days are shorter, bringing winter. The common belief that Earth is closer to the sun in summer is a myth; distance has little to do with it.","questions":[{"question":"What causes the seasons?","choices":["Earth's tilted axis","Earth's distance from the sun","the moon's orbit","changing ocean currents"],"answer":"Earth's tilted axis"},{"question":"What happens when a half of Earth tilts toward the sun?","choices":["it gets more direct sunlight","it gets colder","it loses its days","it stops rotating"],"answer":"it gets more direct sunlight"},{"question":"In the passage, the word myth means?","choices":["a false belief","a proven fact","a hard test","a kind of season"],"answer":"a false belief"}]},{"text":"Octopuses are among the most intelligent invertebrates. They can solve puzzles, open jars, and even learn by watching other octopuses. In labs, some have escaped from sealed tanks by squeezing through tiny gaps, since their bodies have no bones. Scientists believe their intelligence helps them hunt, hide from predators, and explore, even though they live only a few years.","questions":[{"question":"Why can octopuses squeeze through tiny gaps?","choices":["their bodies have no bones","they are very small","they can shrink to a dot","they have sharp claws"],"answer":"their bodies have no bones"},{"question":"Which is an example of octopus intelligence?","choices":["opening jars","swimming in circles","sleeping all day","changing the tide"],"answer":"opening jars"},{"question":"What is surprising about octopuses?","choices":["they are smart but live only a few years","they live for centuries","they cannot move","they avoid the ocean"],"answer":"they are smart but live only a few years"}]},{"text":"An electric circuit is a closed path that lets electricity flow. A simple circuit has a power source, such as a battery, wires, and a device like a light bulb. When the path is complete, electricity travels from the battery through the wires to the bulb, making it glow. If a switch opens the path, the flow stops and the light goes out, which is exactly how a light switch works in your home.","questions":[{"question":"What is needed for a simple circuit?","choices":["a power source, wires, and a device","only a battery","a magnet and a rope","water and metal"],"answer":"a power source, wires, and a device"},{"question":"What happens when a switch opens the path?","choices":["the electricity stops flowing","the bulb gets brighter","the battery grows","the wires melt"],"answer":"the electricity stops flowing"},{"question":"What does the passage compare a circuit to?","choices":["a light switch at home","a river with rocks","a garden hose","a school bus route"],"answer":"a light switch at home"}]},{"text":"The first Olympic Games took place in ancient Greece more than 2,700 years ago. They were held every four years in Olympia to honor Zeus, the king of the gods. Early events included running, wrestling, and chariot racing. During the Games, wars between city-states were paused so that athletes and spectators could travel safely. Winners received olive wreaths rather than medals.","questions":[{"question":"Who were the ancient Games held to honor?","choices":["Zeus","Apollo","Athena","Hercules"],"answer":"Zeus"},{"question":"Why were wars paused during the Games?","choices":["so people could travel safely","because of a storm","to save money","to build a stadium"],"answer":"so people could travel safely"},{"question":"What did winners receive?","choices":["olive wreaths","gold medals","silver cups","bags of coins"],"answer":"olive wreaths"}]},{"text":"Bats find their way in the dark using echolocation. A bat sends out high-pitched sounds that humans cannot hear. When the sounds hit an object, such as an insect, they bounce back as echoes. The bat's brain uses the time the echo takes to return to figure out the object's size, shape, and distance. Thanks to this ability, bats can catch tiny insects in complete darkness.","questions":[{"question":"How do bats find objects in the dark?","choices":["by listening to echoes","by smelling the air","by feeling the wind","by seeing well at night"],"answer":"by listening to echoes"},{"question":"What does the delay before an echo returns tell a bat?","choices":["how far away an object is","what color it is","how old it is","how tasty it is"],"answer":"how far away an object is"},{"question":"In the passage, the word echoes means?","choices":["sounds that bounce back","loud roars","soft songs","whispers of wind"],"answer":"sounds that bounce back"}]},{"text":"Composting turns kitchen scraps and yard waste into rich soil. Microscopic organisms, along with worms and insects, break down items like vegetable peels, coffee grounds, and dead leaves. A healthy compost pile needs a balance of moist green materials and dry brown materials, plus some air. After several months, the pile becomes dark, crumbly compost that gardeners mix into soil to help plants grow, while also keeping waste out of landfills.","questions":[{"question":"What do organisms do in a compost pile?","choices":["break down scraps into soil","turn scraps into plastic","keep the pile cold","stop the smell forever"],"answer":"break down scraps into soil"},{"question":"What does a healthy pile need?","choices":["a mix of green and brown materials","only dry sand","only plastic wrap","no air at all"],"answer":"a mix of green and brown materials"},{"question":"What are two benefits of composting?","choices":["richer soil and less landfill waste","more trash and less soil","louder gardens","faster cars"],"answer":"richer soil and less landfill waste"}]}]},"synonyms":{"easy":{"mad":"angry","sick":"ill","close":"near","pal":"friend","kid":"child","glad":"happy","story":"tale","road":"street","rock":"stone","start":"begin","end":"finish","leap":"jump","chilly":"cold","sleepy":"tired","unhappy":"sad","yell":"shout","grin":"smile","gift":"present","hurry":"rush","trash":"garbage","pick":"choose","repair":"fix","large":"big","little":"small","speak":"talk"},"hard":{"ample":"plentiful","brief":"short","detest":"hate","endure":"tolerate","abandon":"desert","adore":"cherish","anxious":"nervous","assist":"help","bizarre":"strange","commence":"start","courteous":"respectful","crucial":"essential","dwell":"reside","eager":"enthusiastic","fragrant":"aromatic","genuine":"authentic","hazardous":"dangerous","hilarious":"amusing","inquire":"ask","luxurious":"lavish","mimic":"imitate","obstinate":"headstrong","purchase":"buy","rapid":"swift","tremble":"shake","vacant":"empty","wealthy":"affluent"}},"antonyms":{"easy":{"cold":"hot","night":"day","wake":"sleep","give":"take","come":"go","high":"low","long":"short","fat":"thin","dark":"bright","slow":"fast","clean":"dirty","empty":"full","old":"new","sad":"glad","yes":"no","in":"out","on":"off","over":"under","below":"above","wrong":"right","sour":"sweet","smile":"frown","deep":"shallow","narrow":"wide","soft":"hard","lost":"found","boy":"girl"},"hard":{"arrogant":"humble","complex":"simple","conserve":"waste","decrease":"increase","defend":"attack","disperse":"gather","diminish":"expand","elevate":"lower","fertile":"barren","flourish":"wither","guilty":"blameless","hinder":"assist","intentional":"accidental","junior":"senior","liberty":"captivity","minimum":"maximum","mature":"immature","profit":"loss","reveal":"conceal","scatter":"collect","temporary":"permanent","vague":"precise","urban":"rural","zenith":"nadir","ascent":"descent"}},"rhymes":{"easy":[["pig","wig","dig","fig","jig"],["hop","mop","pop","shop","drop"],["bug","hug","rug","jug","tug"],["pan","fan","man","ran","van"],["pen","ten","den","men","then"],["fox","box","socks","rocks","locks"],["sing","ring","wing","swing","string"],["log","frog","fog","jog","hog"],["nut","cut","hut","shut","but"],["tree","free","knee","three","bee"],["boat","goat","float","note","vote"],["train","brain","chain","drain","plain"],["hill","fill","will","pill","spill"],["ship","chip","lip","trip","zip"],["kite","bite","right","white","quite"],["wall","fall","tall","small","call"],["nail","tail","mail","sail","pail"],["cow","now","how","bow","wow"],["sky","fly","cry","dry","try"],["clock","rock","sock","block","knock"]],"hard":[["nation","vacation","celebration","creation","education"],["weather","feather","leather","together","whether"],["through","blue","crew","threw","drew"],["fright","might","tight","delight","polite"],["scene","green","machine","between","routine"],["dough","glow","below","although","tomorrow"],["wear","bear","share","stare","prepare"],["grain","explain","complain","sustain","remain"],["cheer","appear","clear","steer","sincere"],["voice","choice","rejoice","invoice"],["trouble","double","bubble","rubble"],["flame","frame","shame","became","tame"],["believe","achieve","receive","sleeve","weave"],["mother","brother","other","another","smother"],["motion","ocean","lotion","potion","devotion"]]},"analogies":[["glove","hand","sock","foot"],["whale","ocean","camel","desert"],["pen","write","knife","cut"],["ear","hear","nose","smell"],["chef","kitchen","doctor","hospital"],["cub","bear","calf","cow"],["kitten","cat","foal","horse"],["cold","freezing","hot","boiling"],["small","tiny","big","huge"],["happy","smile","sad","frown"],["pig","oink","duck","quack"],["run","fast","crawl","slow"],["page","book","leaf","tree"],["driver","car","pilot","plane"],["teacher","school","chef","restaurant"],["lamp","light","fan","air"],["brush","paint","pen","ink"],["milk","cow","wool","sheep"],["egg","chicken","acorn","oak"],["thin","thick","short","tall"],["above","below","before","after"],["dry","desert","wet","swamp"],["freeze","ice","boil","steam"],["read","book","watch","movie"],["snow","winter","flowers","spring"],["horse","stable","cow","barn"],["shirt","wear","spoon","eat"],["ocean","salty","river","fresh"],["tall","giraffe","small","mouse"],["curtain","window","blanket","bed"]],"word_problem_templates":{"add":["{name} counted {a} {item} in the morning and {b} more {item} in the afternoon. How many {item} did {name} count in all?","A shelf holds {a} {item}. {name} puts {b} more {item} on it. How many {item} are on the shelf now?","{name} won {a} {item} at the fair and got {b} more {item} from a friend. How many {item} does {name} have?","On Saturday {name} found {a} {item}. On Sunday {name} found {b} {item}. How many {item} did {name} find over the weekend?","There were {a} {item} in the box. A helper added {b} more {item}. How many {item} are in the box now?","{name} saved {a} {item} last week and {b} {item} this week. How many {item} has {name} saved altogether?"],"sub":["{name} had {a} {item} and used {b} of them for a project. How many {item} does {name} have left?","A basket held {a} {item}. {name} took out {b} {item}. How many {item} are still in the basket?","{name} started the day with {a} {item} and lost {b} {item} on the way to school. How many {item} does {name} have now?","There were {a} {item} on the desk. Class started, and {b} {item} were handed out. How many {item} are still on the desk?","{name} collected {a} {item} and traded away {b} {item}. How many {item} are left with {name}?","{name} had {a} {item} and gave {b} of them to a friend. How many {item} does {name} still have?"],"mul":["{name} arranges {item} in {a} rows with {b} {item} in each row. How many {item} are there in all?","Each of {a} friends brings {b} {item} to the party. How many {item} do they bring altogether?","{name} puts {b} {item} in each of {a} bags. How many {item} does {name} pack in total?","A store sells {item} in packs of {b}. {name} buys {a} packs. How many {item} does {name} get?","There are {a} tables and each table has {b} {item}. How many {item} are on the tables?","{name} gets {b} {item} every day for {a} days. How many {item} does {name} get in all?"],"div":["{name} has {a} {item} to split equally into {b} piles. How many {item} go in each pile?","A teacher hands out {a} {item} equally to {b} students. How many {item} does each student get?","{name} packs {a} {item} into {b} equal boxes. How many {item} are in each box?","{a} {item} are shared equally by {b} teams. How many {item} does each team receive?","{name} sorts {a} {item} into {b} equal groups. How many {item} are in each group?","If {b} friends share {a} {item} equally, how many {item} does each friend get?"]}},{"id":"2026-09-30-advanced-vocabulary","released":"2026-09-30","kind":"manual","reading_passages":{"0":[{"text":"Mia visited a museum and saw a giant dinosaur skeleton. The dinosaur was taller than a house! Mia's favorite part was touching a real dinosaur tooth. She told everyone about her wonderful adventure.","questions":[{"question":"What did Mia see at the museum?","choices":["A shiny red firetruck","A huge space rocket","A talking robot","A dinosaur skeleton"],"answer":"A dinosaur skeleton"},{"question":"What was Mia's favorite part?","choices":["Eating a big birthday cake","Riding on a school bus","Watching a short movie","Touching a dinosaur tooth"],"answer":"Touching a dinosaur tooth"},{"question":"How did Mia feel about her trip?","choices":["It was wonderful","It was boring","It was scary","It was sad"],"answer":"It was wonderful"}],"photo":"images/flashcards/house.jpg"},{"text":"In the butterfly garden, hundreds of colorful butterflies fluttered everywhere. Ben watched one butterfly land gently on a flower. He stayed completely still so he would not frighten it away.","questions":[{"question":"Where was Ben?","choices":["Inside a school bus","Outside a small bakery","At a swimming pool","In a butterfly garden"],"answer":"In a butterfly garden"},{"question":"Why did Ben stay still?","choices":["Because he was playing a game of hide and seek","Because it was cold outside","Because he wanted to take a nap","So he would not frighten the butterfly"],"answer":"So he would not frighten the butterfly"}],"photo":"images/flashcards/flower.jpg"},{"text":"A helicopter landed on the school playground. Everyone was so excited! A pilot explained how the helicopter could fly straight up into the sky. Zoe decided she wanted to become a pilot someday.","questions":[{"question":"What landed on the playground?","choices":["A fast sailboat","A long train","A big bicycle","A helicopter"],"answer":"A helicopter"},{"question":"What does Zoe want to become?","choices":["A pilot","A teacher","A doctor","A chef"],"answer":"A pilot"}],"photo":"images/flashcards/up.jpg"},{"text":"At the aquarium, a stingray glided gently past the glass. Noah pressed his hand against the window. The stingray seemed curious and swam back and forth, as if it wanted to say hello.","questions":[{"question":"What glided past the glass?","choices":["A stingray","A dolphin","A duck","A turtle"],"answer":"A stingray"},{"question":"What did Noah do?","choices":["Climbed over the glass wall to see inside","Fed the fish a little snack","Took a nap on a bench","Pressed his hand against the window"],"answer":"Pressed his hand against the window"}],"photo":"images/flashcards/glass.jpg"},{"text":"In science class, the students built a model volcano together. They mixed vinegar and baking soda inside it. Orange bubbles erupted out of the top, and everyone cheered with excitement.","questions":[{"question":"What did the students build?","choices":["A tall wooden birdhouse","A paper puppet","A small sandcastle","A model volcano"],"answer":"A model volcano"},{"question":"What happened when they mixed the vinegar and baking soda?","choices":["Orange bubbles erupted","It turned into ice","Nothing happened","It became quiet"],"answer":"Orange bubbles erupted"}],"photo":"images/flashcards/volcano.jpg"},{"text":"At the planetarium, Lily leaned back in her chair and looked up. Suddenly, thousands of stars appeared above her! A narrator explained the names of different planets floating across the ceiling.","questions":[{"question":"Where was Lily?","choices":["At the planetarium","At a farm","At a pool","At a bakery"],"answer":"At the planetarium"},{"question":"What did Lily see above her?","choices":["Hundreds of balloons","A big bright rainbow","Some flying birds","Thousands of stars"],"answer":"Thousands of stars"}],"photo":"images/flashcards/up.jpg"}],"1":[{"text":"Meteorologists use powerful instruments to track hurricanes forming over warm ocean water. Satellites orbiting far above Earth capture images of swirling clouds, while specialized aircraft actually fly directly into the storm to measure wind speed and pressure. This information helps forecasters predict where a hurricane might travel next, giving coastal communities enough warning to prepare safely. Even with advanced technology, predicting the exact path of a hurricane remains remarkably difficult.","questions":[{"question":"What do meteorologists use to track hurricanes?","choices":["Old paper maps and a compass","Telescopes pointed at the moon at night","Only their eyes and a ruler","Powerful instruments and satellites"],"answer":"Powerful instruments and satellites"},{"question":"Why do specialized aircraft fly into storms?","choices":["To rescue people stuck in the storm","To deliver food to coastal towns","To take vacation photos for tourists","To measure wind speed and pressure"],"answer":"To measure wind speed and pressure"},{"question":"In the passage, the word \"remarkably\" means?","choices":["Not at all","Quite quickly","Rather sadly","Very notably"],"answer":"Very notably"}]},{"text":"Glassmaking begins with ordinary sand, which is heated inside a furnace until it reaches a temperature hot enough to turn the sand into a glowing, syrupy liquid. A skilled glassblower gathers a small amount of this molten glass onto the end of a long metal pipe and blows a steady breath through it, forming a bubble that can be shaped into bowls, vases, or ornaments. Because the glass cools and hardens within minutes, glassblowers must work with impressive speed and precision, constantly reheating the piece to keep it workable.","questions":[{"question":"What does heating sand in a furnace produce?","choices":["A cold, clear puddle of water","A thick cloud of grey smoke","A hard, heavy brick","A glowing, syrupy liquid"],"answer":"A glowing, syrupy liquid"},{"question":"Why must glassblowers work quickly?","choices":["The furnace shuts off automatically after a while","The metal pipe becomes too heavy to lift","The supply of sand runs out quickly","The glass cools and hardens within minutes"],"answer":"The glass cools and hardens within minutes"},{"question":"In the passage, \"precision\" most nearly means?","choices":["Careful accuracy","Great speed","Loud noise","Bright color"],"answer":"Careful accuracy"}],"photo":"images/flashcards/glass.jpg"},{"text":"Chocolate begins as a bitter seed called a cacao bean, harvested from large pods that grow directly on the trunks of cacao trees in tropical rainforests. After the beans are removed from the pod, they are left to ferment for several days, developing much of the rich flavor we associate with chocolate, before being dried, roasted, and ground into a thick paste. Ancient civilizations in Mesoamerica actually drank chocolate as a bitter, spiced beverage centuries before anyone added sugar to create the sweet treat most people recognize today.","questions":[{"question":"Where do cacao pods grow?","choices":["Deep underground like carrots","Floating on the leaves of tall palm trees","Inside the petals of large flowers","Directly on the trunks of cacao trees"],"answer":"Directly on the trunks of cacao trees"},{"question":"What happens to cacao beans before they are roasted?","choices":["They ferment for several days","They are frozen","They are painted","They are planted again"],"answer":"They ferment for several days"},{"question":"How did ancient Mesoamerican civilizations drink chocolate?","choices":["As a bitter, spiced beverage","As a sweet frozen treat","Mixed with milk and sugar","They did not drink chocolate"],"answer":"As a bitter, spiced beverage"}]},{"text":"Beavers are considered nature's engineers because of the elaborate dams they construct using branches, mud, and stones. By blocking a stream with a dam, a beaver creates a deep, calm pond, which protects the entrance to its lodge from predators and keeps the water from freezing solid in winter. Remarkably, beavers can detect the sound of running water and will instinctively work to patch any gap in a dam, even reacting to a recording of trickling water played near an already solid structure.","questions":[{"question":"Why are beavers called nature's engineers?","choices":["Because they build bridges for people to cross","Because they dig deep tunnels under cities","Because they can swim faster than fish","Because of the elaborate dams they construct"],"answer":"Because of the elaborate dams they construct"},{"question":"What does a beaver's dam create?","choices":["A deep, calm pond","A dry desert","A rocky hill","A sandy beach"],"answer":"A deep, calm pond"},{"question":"What will a beaver instinctively do if it hears running water?","choices":["Work to patch a gap in the dam","Swim away immediately","Stop building entirely","Search for new territory"],"answer":"Work to patch a gap in the dam"}],"photo":"images/flashcards/mud.jpg"},{"text":"Every late winter, when nights are still freezing but days begin to warm, sap starts flowing upward through sugar maple trees. Farmers drill a small hole into the trunk and insert a spout, allowing the clear, watery sap to drip slowly into a collection bucket. Because the sap contains only about two percent sugar, it takes roughly forty gallons of sap, boiled for hours to evaporate the water, to produce just a single gallon of the thick, amber syrup found on breakfast tables.","questions":[{"question":"When does sap start flowing in sugar maple trees?","choices":["Only in autumn, right after the leaves fall off","Only in the heat of the summer","In the middle of a heavy snowstorm","Late winter, when nights freeze and days warm"],"answer":"Late winter, when nights freeze and days warm"},{"question":"How much sap does it take to produce one gallon of syrup?","choices":["Roughly forty gallons","Exactly one gallon","About two gallons","A single cup"],"answer":"Roughly forty gallons"},{"question":"What is this passage mostly about?","choices":["A simple recipe for fluffy pancakes","The history of furniture made from maple wood","How a maple tree grows from a seed","How maple syrup is made from tree sap"],"answer":"How maple syrup is made from tree sap"}]},{"text":"Bats navigate pitch-black caves and hunt fast-moving insects at night using a remarkable technique called echolocation. A bat emits a rapid series of high-pitched clicks, far too high for human ears to detect, and then listens carefully as those sound waves bounce off nearby objects and return as echoes. By analyzing tiny differences in timing and pitch between clicks, a bat's brain constructs a detailed picture of its surroundings, precise enough to detect an insect smaller than a grain of rice while flying at full speed.","questions":[{"question":"What technique do bats use to navigate in the dark?","choices":["Echolocation","Bright eyesight","Following scent trails","Sensing heat"],"answer":"Echolocation"},{"question":"What does a bat listen for after making clicking sounds?","choices":["Other bats calling back to them","Thunder rumbling across the whole valley","Their own heartbeat slowing down","Echoes bouncing off nearby objects"],"answer":"Echoes bouncing off nearby objects"},{"question":"In the passage, \"emits\" most nearly means?","choices":["Soaks up","Hides away","Breaks apart","Sends out"],"answer":"Sends out"}],"photo":"images/flashcards/bat.jpg"}],"2":[{"text":"Inside every green leaf, microscopic structures called chloroplasts perform one of the most essential chemical reactions on Earth: photosynthesis. Using a pigment called chlorophyll, which gives leaves their green color, plants absorb sunlight and convert carbon dioxide and water into glucose, a simple sugar that fuels the plant's growth. Oxygen, released as a byproduct of this reaction, happens to be the very gas that humans and countless other organisms depend on to breathe. Scientists estimate that phytoplankton, microscopic photosynthesizing organisms drifting throughout the ocean, generate more than half of the oxygen in Earth's atmosphere, even though most people associate photosynthesis exclusively with forests and land plants. Without this remarkable chemical process occurring continuously across the planet, most complex life as we currently understand it could not exist.","questions":[{"question":"What pigment allows plants to absorb sunlight?","choices":["Chlorophyll","Oxygen","Glucose","Carbon dioxide"],"answer":"Chlorophyll"},{"question":"According to the passage, where does much of Earth's oxygen actually come from?","choices":["Phytoplankton in the ocean","Only forests","Only deserts","Underground caves"],"answer":"Phytoplankton in the ocean"},{"question":"In the passage, the word \"byproduct\" most likely means?","choices":["The main goal that a process aims to reach","A scientific tool used to measure light","A special type of plant","A side result of a larger process"],"answer":"A side result of a larger process"}],"photo":"images/flashcards/leaf.jpg"},{"text":"The Great Wall of China was not built as a single continuous project but rather assembled, extended, and repaired across more than two thousand years by numerous dynasties, each contributing new sections using whatever materials were locally available. In mountainous regions, builders relied on stone and brick; in desert areas, they compacted layers of earth, reeds, and gravel that have proven surprisingly durable. Despite popular legend, the wall cannot actually be seen with the naked eye from space, since its width, often only a few meters, is far too narrow relative to the vast distances involved. Historians estimate that constructing and maintaining the wall cost the lives of countless laborers, many of whom were soldiers, prisoners, or conscripted peasants working under grueling conditions.","questions":[{"question":"How was the Great Wall of China actually built, according to the passage?","choices":["Built entirely in a single decade","Made only out of solid stone throughout","Designed and built by one powerful emperor alone","Extended over centuries by many dynasties"],"answer":"Extended over centuries by many dynasties"},{"question":"What does the passage say about seeing the wall from space?","choices":["It cannot actually be seen with the naked eye","It is the only human structure visible from space","Astronauts photograph it every year","It glows at night and is easy to spot"],"answer":"It cannot actually be seen with the naked eye"},{"question":"What is the central idea of this passage?","choices":["It was built quickly in one decade using only imported materials","It is only a legend with no real historical basis","It was built mainly as decoration for the emperor's gardens","It was a massive, centuries-long effort with a heavy human cost"],"answer":"It was a massive, centuries-long effort with a heavy human cost"}],"photo":"images/flashcards/not.jpg"},{"text":"Glaciers, often described as slow-moving rivers of ice, form when accumulated snow compresses under its own weight over many years, eventually transforming into dense ice that begins flowing downhill under the pull of gravity. As a glacier advances, embedded rocks and sediment scrape against the underlying bedrock like sandpaper, gradually carving out distinctive U-shaped valleys, unlike the narrower V-shaped valleys typically formed by flowing rivers. When a glacier eventually retreats, often due to a warming climate, it leaves behind telltale features such as ridges of debris called moraines, revealing exactly how far the ice once extended. Studying these ancient formations helps scientists reconstruct Earth's climate history stretching back hundreds of thousands of years.","questions":[{"question":"How does a glacier's movement shape the land beneath it?","choices":["It has almost no effect on the land beneath it at all","It only changes the very top layer of soil","It smooths the ground into perfectly flat plains","It carves U-shaped valleys as it scrapes the rock"],"answer":"It carves U-shaped valleys as it scrapes the rock"},{"question":"What do moraines reveal to scientists?","choices":["How far the ice once extended","The exact temperature of the ice","The age of nearby rivers","The direction the wind blows"],"answer":"How far the ice once extended"},{"question":"In the passage, \"telltale\" most nearly means?","choices":["Revealing or informative","Completely hidden","Loud and noisy","Extremely rare"],"answer":"Revealing or informative"}],"photo":"images/flashcards/ice.jpg"},{"text":"Louis Braille lost his sight in both eyes after a childhood accident in his father's workshop, yet by the age of fifteen he had devised an entirely new system that would eventually transform literacy for blind people worldwide. Rather than relying on the raised, oversized letters used in earlier systems, which were slow to read and difficult to reproduce, Braille adapted a military code originally designed for silent nighttime communication, condensing it into a compact grid of six raised dots that could represent any letter, number, or punctuation mark. Each unique arrangement of dots can be read quickly by sliding a fingertip across the page, and because the system is based on patterns rather than exact letter shapes, it was later adapted for languages and even musical notation far beyond what Braille himself likely imagined.","questions":[{"question":"What inspired Louis Braille's writing system?","choices":["An ancient Egyptian picture alphabet","A system borrowed from sign language","A popular children's board game from France","A military code for silent night messages"],"answer":"A military code for silent night messages"},{"question":"How many raised dots make up the basic Braille grid?","choices":["Six","Two","Twelve","Twenty"],"answer":"Six"},{"question":"What is the central idea of this passage?","choices":["Braille invented a brand new spoken language for the deaf","Braille's system was never adopted by anyone anywhere","Braille's military code was too complicated for blind students to use","Braille's compact dot system transformed reading for blind people"],"answer":"Braille's compact dot system transformed reading for blind people"}],"photo":"images/flashcards/slow.jpg"},{"text":"Venus flytraps, native to a small coastal region of North and South Carolina, capture insects using specialized leaves lined with tiny trigger hairs. When an unsuspecting insect brushes against two of these hairs within about twenty seconds of each other, the trap snaps shut in less than a second, one of the fastest movements found anywhere in the plant kingdom. Digestive enzymes then slowly dissolve the insect over roughly a week, allowing the plant to absorb nutrients, particularly nitrogen, that are scarce in the nutrient-poor, boggy soil where these plants naturally grow. Interestingly, a trap that closes around something inedible, like a falling raindrop, typically reopens within half a day, conserving the considerable amount of energy required to reset the mechanism.","questions":[{"question":"What triggers a Venus flytrap to snap shut?","choices":["Very cold temperatures during the night","Loud noises coming from nearby animals","Bright sunlight shining on its leaves for hours","An insect brushing against trigger hairs"],"answer":"An insect brushing against trigger hairs"},{"question":"Why do Venus flytraps need to capture insects?","choices":["To protect their leaves from heavy rain","To make more seeds for the next season","To attract other plants to grow nearby","To get nutrients scarce in their soil"],"answer":"To get nutrients scarce in their soil"},{"question":"In the passage, \"boggy\" most likely describes soil that is?","choices":["Wet and marshy","Extremely dry","Made of sand","Frozen solid"],"answer":"Wet and marshy"}],"photo":"images/flashcards/insect.jpg"},{"text":"When a honeybee scout discovers a rich source of nectar, it returns to the hive and performs an intricate waggle dance to share the discovery with its fellow workers. By moving in a repeated figure-eight pattern and vigorously shaking its abdomen along the central line of the figure, the bee encodes both the direction and distance of the food source relative to the sun's position in the sky. The duration of each waggle run corresponds directly to distance, while the angle of the dance relative to vertical indicates the precise direction to fly. Remarkably, other bees in the pitch-dark hive interpret this dance purely through touch and vibration, then depart and navigate directly to a flower patch they have never personally seen.","questions":[{"question":"What does a honeybee do after discovering nectar?","choices":["Eats all of the nectar alone","Flies back and forth at random","Stays outside the hive until the next morning","Performs a dance to share the location"],"answer":"Performs a dance to share the location"},{"question":"What does the duration of the waggle run indicate?","choices":["The age of the dancing bee","The total size of the hive","The color of the nearest flowering plants","The distance to the food source"],"answer":"The distance to the food source"},{"question":"In the passage, \"encodes\" most nearly means?","choices":["Destroys everything it touches","Hides something from other bees","Grows larger over a long time","Sends information in a pattern"],"answer":"Sends information in a pattern"}],"photo":"images/flashcards/bee.jpg"}]}},{"id":"2026-10-04-weekly-reading","released":"2026-10-04","kind":"weekly","reading_passages":{"0":[{"text":"The garbage truck comes on Monday. It is big and green. It picks up the trash cans on our street.","questions":[{"question":"What color is the garbage truck?","choices":["blue","yellow","green","red"],"answer":"green"},{"question":"What day does the garbage truck come?","choices":["Sunday","Monday","Friday","Tuesday"],"answer":"Monday"}]},{"text":"Ana washes her hands with soap and water. She sings a song while she scrubs. Now her hands are clean.","questions":[{"question":"What does Ana use to wash her hands?","choices":["sand","soap and water","paint","milk"],"answer":"soap and water"},{"question":"What does Ana do while she scrubs?","choices":["She sings a song.","She reads a book.","She eats lunch.","She takes a nap."],"answer":"She sings a song."}],"photo":"images/flashcards/soap.jpg"},{"text":"Ben brushes his teeth after breakfast. His toothbrush is blue. He brushes for two minutes.","questions":[{"question":"When does Ben brush his teeth?","choices":["at school","in the bath","after breakfast","at the park"],"answer":"after breakfast"},{"question":"What color is Ben's toothbrush?","choices":["green","orange","blue","pink"],"answer":"blue"}]},{"text":"The train goes down the long track. It has five cars. The train horn goes toot, toot!","questions":[{"question":"How many cars does the train have?","choices":["ten","five","two","one"],"answer":"five"},{"question":"What sound does the train horn make?","choices":["buzz, buzz","toot, toot","quack, quack","moo, moo"],"answer":"toot, toot"}],"photo":"images/flashcards/train.jpg"},{"text":"Dad makes a sandwich for lunch. It has cheese and turkey. He cuts it into two triangles.","questions":[{"question":"What is in the sandwich?","choices":["eggs and ham","jam and peanut butter","fish and rice","cheese and turkey"],"answer":"cheese and turkey"},{"question":"What shape does Dad cut the sandwich into?","choices":["stars","circles","triangles","hearts"],"answer":"triangles"}]},{"text":"Kim plays the drum at music time. Boom, boom, boom! Her friends clap along to the beat.","questions":[{"question":"What does Kim play?","choices":["the flute","the piano","the guitar","the drum"],"answer":"the drum"},{"question":"What do Kim's friends do?","choices":["clap along","go to sleep","eat snacks","run outside"],"answer":"clap along"}],"photo":"images/flashcards/drum.jpg"},{"text":"The clock on the kitchen wall is round. It goes tick, tock all day. Its hands point to the numbers.","questions":[{"question":"What shape is the clock?","choices":["round","triangle","square","star"],"answer":"round"},{"question":"Where is the clock?","choices":["in the car","under the bed","on the porch","on the kitchen wall"],"answer":"on the kitchen wall"}],"photo":"images/flashcards/clock.jpg"},{"text":"Sam helps set the table for dinner. He puts a fork and a spoon next to each plate. Mom says thank you.","questions":[{"question":"What does Sam put next to each plate?","choices":["a hat and a sock","a cup of juice","a fork and a spoon","a toy and a ball"],"answer":"a fork and a spoon"},{"question":"What does Mom say?","choices":["good night","hurry up","thank you","hello"],"answer":"thank you"}],"photo":"images/flashcards/fork.jpg"},{"text":"The fire truck is shiny and red. It has a long ladder on top. Its siren is very loud.","questions":[{"question":"What is on top of the fire truck?","choices":["a long ladder","a slide","a tree","a big boat"],"answer":"a long ladder"},{"question":"How does the siren sound?","choices":["very loud","very quiet","like a bird","like a cat"],"answer":"very loud"}]},{"text":"At the library, Ms. Bell reads a book at story time. The book is about a silly goat. All the kids laugh.","questions":[{"question":"What is the book about?","choices":["a big ship","a red car","a sleepy bear","a silly goat"],"answer":"a silly goat"},{"question":"What do the kids do?","choices":["laugh","cry","leave","sleep"],"answer":"laugh"}],"photo":"images/flashcards/book.jpg"},{"text":"Tess has a box of blocks. A new girl named June sits next to her. Tess shares her blocks, and they build a castle together.","questions":[{"question":"What does Tess share?","choices":["her blocks","her lunch","her book","her hat"],"answer":"her blocks"},{"question":"What do Tess and June build?","choices":["a castle","a car","a boat","a bridge"],"answer":"a castle"}]},{"text":"Grandpa takes Lin to the farm stand. They buy six ears of corn and a big bag of peaches.","questions":[{"question":"How many ears of corn do they buy?","choices":["two","six","nine","one"],"answer":"six"},{"question":"Who takes Lin to the farm stand?","choices":["the bus driver","Grandpa","the teacher","her sister"],"answer":"Grandpa"}],"photo":"images/flashcards/farm.jpg"},{"text":"The leaves turn orange and red in the fall. Max rakes them into a big pile. Then he jumps right in!","questions":[{"question":"What colors are the leaves?","choices":["black and gray","blue and purple","pink and white","orange and red"],"answer":"orange and red"},{"question":"What does Max do after he rakes?","choices":["He jumps in the pile.","He rides a bike.","He goes to bed.","He eats a snack."],"answer":"He jumps in the pile."}]},{"text":"Ruby sorts her crayons by color. She puts all the red ones in one cup. She puts all the blue ones in another cup.","questions":[{"question":"How does Ruby sort her crayons?","choices":["by size","by smell","by name","by color"],"answer":"by color"},{"question":"Where does Ruby put the red crayons?","choices":["in one cup","in her shoe","on the floor","in a bag"],"answer":"in one cup"}]},{"text":"The tugboat is small, but it is very strong. It pushes a giant ship slowly into the harbor.","questions":[{"question":"What size is the tugboat?","choices":["small","wide","giant","long"],"answer":"small"},{"question":"What does the tugboat push?","choices":["a red car","a giant ship","a tall tree","a big truck"],"answer":"a giant ship"}],"photo":"images/flashcards/ship.jpg"},{"text":"Eva goes to the doctor for a checkup. The doctor listens to her heart. Eva gets a sticker for being brave.","questions":[{"question":"What does the doctor listen to?","choices":["her heart","a bird","the radio","a song"],"answer":"her heart"},{"question":"What does Eva get?","choices":["a sticker","a cake","a puppy","a bike"],"answer":"a sticker"}]},{"text":"Nico packs a picnic for the park. He packs grapes, crackers, and apple juice. He brings a blanket to sit on.","questions":[{"question":"What drink does Nico pack?","choices":["lemonade","hot cocoa","apple juice","milk"],"answer":"apple juice"},{"question":"What will Nico sit on?","choices":["a chair","a rock","a blanket","a bench"],"answer":"a blanket"}],"photo":"images/flashcards/grapes.jpg"},{"text":"Snow falls all night. In the morning, a snowplow clears the road. It pushes the snow to the side.","questions":[{"question":"When does the snow fall?","choices":["after school","all night","in the summer","at lunch"],"answer":"all night"},{"question":"What clears the road?","choices":["a snowplow","a bus","a horse","a bike"],"answer":"a snowplow"}]},{"text":"The mail carrier brings a letter to Owen's house. The letter is from Aunt Rose. She drew a happy sun on it.","questions":[{"question":"Who is the letter from?","choices":["Grandpa","the teacher","a friend at school","Aunt Rose"],"answer":"Aunt Rose"},{"question":"What did Aunt Rose draw?","choices":["a big fish","a red car","a happy sun","a green tree"],"answer":"a happy sun"}]},{"text":"The wind blows hard today. It pushes the clouds across the sky. Jay holds on to his hat.","questions":[{"question":"What does the wind push?","choices":["the clouds","the house","the school","the car"],"answer":"the clouds"},{"question":"What does Jay hold on to?","choices":["his dog","his cup","his hat","his book"],"answer":"his hat"}]}],"1":[{"text":"Lena wanted to send a birthday card to her grandma, who lives far away. She wrote a short note inside and drew a picture of their two cats. Her dad helped her write the address on the envelope and stick a stamp in the corner. Then Lena dropped the card into the blue mailbox. Four days later, Grandma called to say thank you.","questions":[{"question":"What did Lena draw on the card?","choices":["a flower garden","their two cats","a birthday cake","a big house"],"answer":"their two cats"},{"question":"Where did Lena put the stamp?","choices":["on her hand","on the back","in the corner","inside the card"],"answer":"in the corner"},{"question":"How did Lena know Grandma got the card?","choices":["Grandma came to visit.","The card came back.","A teacher told her.","Grandma called to say thank you."],"answer":"Grandma called to say thank you."}]},{"text":"Teeth help us bite and chew our food. To keep them healthy, dentists say we should brush two times a day for two minutes. Brushing removes a sticky layer of germs called plaque. We should also floss to clean between our teeth. Eating fewer sugary snacks and drinking water help, too. Visiting the dentist twice a year keeps a smile bright.","questions":[{"question":"How many times a day should we brush?","choices":["one","ten","two","five"],"answer":"two"},{"question":"What is plaque?","choices":["a sugary snack","a kind of toothbrush","a dentist's tool","a sticky layer of germs"],"answer":"a sticky layer of germs"},{"question":"What is this passage mostly about?","choices":["keeping teeth healthy","how to bake cookies","how dentists drive","why we sleep"],"answer":"keeping teeth healthy"}]},{"text":"Clouds come in many shapes. Puffy white clouds that look like cotton are called cumulus clouds. They often appear on sunny days. Thin, wispy clouds high in the sky are called cirrus clouds. Dark gray clouds that cover the whole sky can bring rain. Watching clouds can help you guess what the weather will do.","questions":[{"question":"What are puffy white clouds called?","choices":["cumulus clouds","cirrus clouds","fog","rain clouds"],"answer":"cumulus clouds"},{"question":"What kind of clouds can bring rain?","choices":["dark gray clouds","puffy white clouds","tiny pink clouds","thin wispy clouds"],"answer":"dark gray clouds"}],"photo":"images/flashcards/rain.jpg"},{"text":"On her first day at a new school, Hana felt nervous. She did not know anyone, and her stomach felt full of butterflies. At lunch, she sat alone at the end of a table. Then a boy named Theo asked if he could sit with her. He liked drawing dragons, and so did Hana. By the end of lunch, they had planned a comic book together.","questions":[{"question":"How did Hana feel on her first day?","choices":["nervous","angry","sleepy","bored"],"answer":"nervous"},{"question":"What did Hana and Theo both like?","choices":["drawing dragons","reading maps","playing soccer","singing songs"],"answer":"drawing dragons"},{"question":"What did they plan by the end of lunch?","choices":["a birthday party","a field trip","a soccer game","a comic book"],"answer":"a comic book"}]},{"text":"Every Saturday, Mateo and his grandpa walk to the farmers market. Farmers bring fruits and vegetables they grew themselves. Mateo's favorite stand sells honey in glass jars. Grandpa likes to buy fresh tomatoes and green beans. Buying food from local farmers helps them earn money, and the food does not have to travel very far.","questions":[{"question":"What does Mateo's favorite stand sell?","choices":["bread","flowers","honey","cheese"],"answer":"honey"},{"question":"When do Mateo and Grandpa go to the market?","choices":["every Monday","every night","every Saturday","once a year"],"answer":"every Saturday"},{"question":"Why is buying from local farmers helpful?","choices":["It makes food travel farther.","It helps them earn money.","It closes the market.","It makes food cost more."],"answer":"It helps them earn money."}],"photo":"images/flashcards/honey.jpg"},{"text":"Mr. Lopez is the crossing guard at Pine Street School. Every morning, he wears a bright orange vest so drivers can see him. When children reach the corner, he holds up a red stop sign. The cars stop, and the kids cross safely. Mr. Lopez knows every student's name and always tells them to have a great day.","questions":[{"question":"Why does Mr. Lopez wear a bright orange vest?","choices":["so drivers can see him","to stay warm in the rain","to look like a pumpkin","to match the school bus"],"answer":"so drivers can see him"},{"question":"What does Mr. Lopez hold up?","choices":["a big umbrella","a lunch box","a green flag","a red stop sign"],"answer":"a red stop sign"},{"question":"What does Mr. Lopez always tell the students?","choices":["to have a great day","to go home","to hurry up","to be quiet"],"answer":"to have a great day"}],"photo":"images/flashcards/vest.jpg"},{"text":"Sea turtles lay their eggs on sandy beaches. A mother turtle digs a hole with her flippers and lays about one hundred eggs. Then she covers them with sand and returns to the ocean. About two months later, the baby turtles hatch. They dig out of the sand and crawl toward the bright water. Many beaches turn off lights at night so the babies do not get confused.","questions":[{"question":"What does the mother turtle use to dig a hole?","choices":["her shell","a stick","her flippers","her mouth"],"answer":"her flippers"},{"question":"About how long until the baby turtles hatch?","choices":["one hour","one year","two months","two days"],"answer":"two months"},{"question":"Why do some beaches turn off lights at night?","choices":["so the turtles grow faster","so the babies do not get confused","so people can sleep","to keep the sand cool"],"answer":"so the babies do not get confused"}]},{"text":"Zoe joined a basketball team this fall. At first, she could not dribble without the ball bouncing away. Her coach told her to use her fingertips, not her palm, and to keep her eyes up. Zoe practiced in her driveway every evening. By the last game, she dribbled down the court and passed to a teammate, who scored!","questions":[{"question":"What did the coach tell Zoe to use?","choices":["her fingertips","her palm","her elbow","both feet"],"answer":"her fingertips"},{"question":"Where did Zoe practice?","choices":["in the library","at the beach","in her driveway","at the zoo"],"answer":"in her driveway"},{"question":"What lesson does this story teach?","choices":["Practice helps you improve.","Coaches are always right.","Basketball is too hard.","Never play sports."],"answer":"Practice helps you improve."}]},{"text":"Wind turbines are tall towers with giant blades that spin when the wind blows. As the blades turn, they spin a machine inside called a generator. The generator makes electricity that travels through wires to homes and schools. Wind is a clean source of energy because it does not make smoke, and the wind will never run out.","questions":[{"question":"What makes the blades spin?","choices":["the rain","the wind","the sun","a gas motor"],"answer":"the wind"},{"question":"What is the machine inside called?","choices":["a pump","an engine","a generator","a battery"],"answer":"a generator"},{"question":"Why is wind called a clean source of energy?","choices":["It only works at night.","It does not make smoke.","It is very loud.","It uses lots of water."],"answer":"It does not make smoke."}]},{"text":"Max and Leo both wanted the swing at recess. Max grabbed the chains, and Leo pulled them back. Soon both boys were upset. Their teacher suggested they take turns, with each boy counting to fifty. Leo went first while Max counted out loud, and then they switched. When the bell rang, both boys agreed it had been a fun recess.","questions":[{"question":"What did both boys want to use?","choices":["the sandbox","the swing","the slide","the ball"],"answer":"the swing"},{"question":"What did the teacher suggest?","choices":["play tag","go inside","share a snack","take turns"],"answer":"take turns"},{"question":"How did the boys feel when the bell rang?","choices":["They were still angry.","They agreed it was fun.","They were lost.","They were sleepy."],"answer":"They agreed it was fun."}]},{"text":"During a thunderstorm, you see lightning before you hear thunder. That is because light travels much faster than sound. You can count the seconds between the flash and the boom. If you count to five, the storm is about one mile away. When you hear thunder, it is a good idea to go indoors and stay safe.","questions":[{"question":"Which do you notice first in a storm?","choices":["lightning","thunder","wind","hail"],"answer":"lightning"},{"question":"If you count to five, how far away is the storm?","choices":["about one foot","about ten miles","about one mile","right overhead"],"answer":"about one mile"},{"question":"What should you do when you hear thunder?","choices":["climb a tree","fly a kite","go indoors","go swimming"],"answer":"go indoors"}]},{"text":"On Sunday, Abuela taught Sofia how to make tortillas. They mixed flour, water, salt, and a little oil into a soft dough. Sofia rolled the dough into small balls and flattened each one with a rolling pin. Abuela cooked them on a hot pan until they puffed up with brown spots. They ate the warm tortillas with beans and rice.","questions":[{"question":"Who taught Sofia to make tortillas?","choices":["her teacher","her brother","Abuela","a chef on TV"],"answer":"Abuela"},{"question":"What did Sofia use to flatten the dough?","choices":["her shoe","a spoon","a book","a rolling pin"],"answer":"a rolling pin"},{"question":"What did they eat with the tortillas?","choices":["cereal and milk","apples and cheese","soup and salad","beans and rice"],"answer":"beans and rice"}]},{"text":"Before the class hike, Ranger Diaz shared some trail rules. Stay on the path so plants do not get trampled. Do not pick flowers, so others can enjoy them too. Carry out all of your trash, even tiny wrappers. 'Take only pictures and leave only footprints,' she said. The students followed the rules and saw a deer drinking from a stream.","questions":[{"question":"Why should hikers stay on the path?","choices":["so plants do not get trampled","to scare the deer","to find hidden treasure","so they can walk faster"],"answer":"so plants do not get trampled"},{"question":"What should hikers do with their trash?","choices":["carry it out","hide it under a rock","bury it","leave it on the path"],"answer":"carry it out"},{"question":"What did the students see?","choices":["a fox on a log","an owl in a tree","a deer drinking from a stream","a bear in a cave"],"answer":"a deer drinking from a stream"}]},{"text":"Ms. Patel's class got a small robot shaped like a ladybug. Students could make it move by pressing arrow buttons on its back. Each button press was one step in a program. To guide the robot through a paper maze, Jamal planned his steps carefully: forward, forward, turn right, forward. When he pressed go, the robot reached the finish line on the first try.","questions":[{"question":"What was the robot shaped like?","choices":["a dog","a rocket","a ladybug","a car"],"answer":"a ladybug"},{"question":"What did each button press stand for?","choices":["one step in a program","one point in a game","one new color","one minute of time"],"answer":"one step in a program"},{"question":"How did Jamal get the robot through the maze?","choices":["He planned his steps carefully.","He carried it.","He shook the robot.","He guessed each step."],"answer":"He planned his steps carefully."}],"photo":"images/flashcards/robot.jpg"},{"text":"The moon seems to change shape during the month, but it is always round. The moon does not make its own light. We see the part that is lit by the sun. When the lit side faces us, we see a full moon. When it faces away, we see a new moon, and the moon looks dark. The whole pattern takes about one month to repeat.","questions":[{"question":"What lights up the moon?","choices":["city lights","the sun","the moon itself","the stars"],"answer":"the sun"},{"question":"What do we see when the lit side faces us?","choices":["a full moon","a new moon","a red moon","no moon"],"answer":"a full moon"},{"question":"How long does the pattern take to repeat?","choices":["about one day","about one hour","about one year","about one month"],"answer":"about one month"}],"photo":"images/flashcards/moon.jpg"},{"text":"Hummingbirds are the smallest birds in the world. Some weigh less than a penny. Their wings beat so fast that they make a humming sound, which is how they got their name. Hummingbirds can fly forward, backward, and even hover in one spot. They use their long, thin beaks to drink sweet nectar from flowers.","questions":[{"question":"How did hummingbirds get their name?","choices":["They live in hives.","They sing loud songs.","Their wings make a humming sound.","They hum at night."],"answer":"Their wings make a humming sound."},{"question":"What do hummingbirds drink from flowers?","choices":["milk","salty water","sweet nectar","juice"],"answer":"sweet nectar"},{"question":"What can hummingbirds do?","choices":["hover in one spot","dig tunnels","swim underwater","run very far"],"answer":"hover in one spot"}]},{"text":"On the way home from school, Ivy found a purple mitten on the sidewalk. It was small, with a white star sewn on it. Ivy thought someone must be missing it. She made a poster that said 'Found: Purple Mitten' and taped it to the playground fence. The next day, a kindergartner named Rosie ran up to thank her.","questions":[{"question":"What did Ivy find?","choices":["a toy car","a blue scarf","a red hat","a purple mitten"],"answer":"a purple mitten"},{"question":"What was sewn on the mitten?","choices":["a green leaf","a yellow moon","a white star","a pink heart"],"answer":"a white star"},{"question":"What does Ivy's poster show about her?","choices":["She is scared.","She is lazy.","She is thoughtful.","She is selfish."],"answer":"She is thoughtful."}]},{"text":"When the fire alarm rang, Mr. Green's class knew just what to do. They stopped their work, left their backpacks, and lined up at the door. They walked quietly down the hall and out to the field. Mr. Green counted everyone to make sure no one was missing. It was only a drill, but practicing helps everyone stay safe in a real emergency.","questions":[{"question":"What did the class leave behind?","choices":["their shoes","their friends","their backpacks","their teacher"],"answer":"their backpacks"},{"question":"Why did Mr. Green count everyone?","choices":["to make sure no one was missing","to start a game","to pick teams","to check homework"],"answer":"to make sure no one was missing"},{"question":"Why do schools practice fire drills?","choices":["to help everyone stay safe","to test the bell","to play outside","to skip math class"],"answer":"to help everyone stay safe"}]},{"text":"Kai wondered why trucks spread salt on icy roads, so he tried an experiment. He put two ice cubes on separate plates and sprinkled salt on only one. After ten minutes, the salty ice cube had melted much more. Kai learned that salt lowers the temperature at which water freezes, so ice melts even when it is cold outside.","questions":[{"question":"What did Kai sprinkle on one ice cube?","choices":["sugar","pepper","sand","salt"],"answer":"salt"},{"question":"What happened to the salty ice cube?","choices":["It stayed the same.","It turned blue.","It melted much more.","It grew bigger."],"answer":"It melted much more."},{"question":"Why do trucks spread salt on icy roads?","choices":["to make cars faster","to help the ice melt","to feed the birds","to paint new lines"],"answer":"to help the ice melt"}],"photo":"images/flashcards/ice.jpg"},{"text":"Nadia was afraid to put her face in the water at swim lessons. Her instructor showed her how to blow bubbles through her nose and mouth. Nadia practiced blowing bubbles in the shallow end every week. Little by little, she felt braver. By the end of summer, she could float on her back and swim across the pool.","questions":[{"question":"What was Nadia afraid to do?","choices":["ride the bus","wear goggles","jump off the diving board","put her face in the water"],"answer":"put her face in the water"},{"question":"What did her instructor show her?","choices":["how to run","how to blow bubbles","how to dive","how to splash"],"answer":"how to blow bubbles"},{"question":"What could Nadia do by the end of summer?","choices":["win a race","swim across the pool","ride a horse","fly a kite"],"answer":"swim across the pool"}]},{"text":"For a class project, Emeka made a family tree. He wrote his name at the bottom, then added his parents above him. Above them, he added his four grandparents. Emeka interviewed his grandpa, who grew up on a farm and walked two miles to school. Emeka learned that every family has stories worth sharing.","questions":[{"question":"Where did Emeka write his name?","choices":["on the back","at the top","at the bottom","on the cover"],"answer":"at the bottom"},{"question":"How many grandparents did Emeka add?","choices":["one","two","four","six"],"answer":"four"},{"question":"What did Emeka learn about his grandpa?","choices":["He had ten dogs.","He grew up on a farm.","He lived in a big city.","He was a pilot."],"answer":"He grew up on a farm."}]},{"text":"Did you know an old milk jug can become a park bench? When plastic is recycled, it is cleaned, chopped into tiny flakes, and melted. The melted plastic is pressed into long boards. Those boards can be used to build benches, picnic tables, and playground parts. Recycled plastic boards do not rot or need paint, so they last a long time.","questions":[{"question":"What happens first to recycled plastic?","choices":["It is cleaned.","It is buried.","It is frozen.","It is painted."],"answer":"It is cleaned."},{"question":"What can recycled plastic boards be used to build?","choices":["metal cans","paper bags","park benches","glass windows"],"answer":"park benches"},{"question":"Why do recycled plastic boards last a long time?","choices":["They are made of wood.","They melt in the sun.","They do not rot or need paint.","They are very soft."],"answer":"They do not rot or need paint."}],"photo":"images/flashcards/milk.jpg"},{"text":"In the fall, Ethan's family visited an apple orchard. Rows of trees were heavy with red and yellow apples. A farmer showed them how to twist an apple gently upward so it would come off without hurting the branch. Ethan filled a whole bag. That night, the family used some of the apples to bake a warm apple crisp.","questions":[{"question":"How should you pick an apple?","choices":["shake the tree","pull it down hard","hit it with a stick","twist it gently upward"],"answer":"twist it gently upward"},{"question":"What colors were the apples?","choices":["red and yellow","orange and pink","blue and purple","white and black"],"answer":"red and yellow"},{"question":"What did the family bake?","choices":["a pumpkin pie","an apple crisp","oatmeal cookies","banana bread"],"answer":"an apple crisp"}],"photo":"images/flashcards/apple.jpg"}],"2":[{"text":"Tardigrades, sometimes called water bears, are tiny animals usually less than half a millimeter long. Under a microscope, they look like chubby bears with eight stubby legs. Tardigrades live in moss, soil, and water all over the world. What makes them remarkable is their toughness. When their surroundings dry out, they curl into a shriveled state called a tun and slow their bodies almost to a stop. In this state, some can survive for years without water, endure freezing cold, and even survive a trip to outer space. When water returns, they unfold and go about their business. Scientists study tardigrades hoping to learn how to protect living cells from extreme conditions.","questions":[{"question":"In the passage, the word remarkable means?","choices":["hard to see","easy to find","very small","worthy of notice"],"answer":"worthy of notice"},{"question":"What is a tun?","choices":["a tiny microscope","a group of tardigrades","a kind of moss tardigrades eat","a dried, curled state that helps tardigrades survive"],"answer":"a dried, curled state that helps tardigrades survive"},{"question":"What is the main idea of the passage?","choices":["Scientists use tardigrades to fly rockets.","Moss is the best place to live.","Tardigrades are a kind of bear.","Tardigrades are tiny animals that survive extreme conditions."],"answer":"Tardigrades are tiny animals that survive extreme conditions."}]},{"text":"In 1783, two French brothers, Joseph and Etienne Montgolfier, noticed that smoke and hot air rose upward. They built a large balloon of fabric and paper and filled it with hot air from a fire. That September, their balloon carried the first living passengers into the sky: a sheep, a duck, and a rooster. All three landed safely. Two months later, two men rode a Montgolfier balloon over Paris, becoming the first people to fly in a balloon that was not tied down. Hot air balloons work because heated air is less dense, or lighter for its size, than the cooler air around it. That difference lets the balloon float upward, much like a cork rising in water.","questions":[{"question":"In the passage, the word dense means?","choices":["heavy for its size","very hot","brightly colored","easy to fold"],"answer":"heavy for its size"},{"question":"Who were the balloon's first passengers?","choices":["a sheep, a duck, and a rooster","a dog and a cat","the two Montgolfier brothers","the king and queen"],"answer":"a sheep, a duck, and a rooster"},{"question":"Why does a hot air balloon rise?","choices":["The paper is lighter than fabric.","Smoke pushes the balloon up.","Hot air is lighter than the cooler air around it.","Wind blows it from below."],"answer":"Hot air is lighter than the cooler air around it."}]},{"text":"For centuries, lighthouses have guided sailors along dangerous coasts. A lighthouse is a tall tower with a powerful light at the top that warns ships of rocks, reefs, and shallow water. Before electricity, keepers lived at the lighthouse and climbed its stairs each evening to light oil lamps and keep them burning all night. In 1822, a French scientist named Augustin Fresnel invented a special lens made of rings of glass that bent light into a strong beam visible for many miles. Each lighthouse also has its own pattern of flashes, so sailors can tell which one they are seeing. Today, most lighthouses are automated, and satellite navigation helps ships find their way, but many lighthouses still shine every night.","questions":[{"question":"In the passage, the word automated means?","choices":["painted in bright colors","built very tall","closed forever","run by machines without a person"],"answer":"run by machines without a person"},{"question":"Why does each lighthouse have its own pattern of flashes?","choices":["so the tower looks pretty","to save lamp oil","to warn of storms only","so sailors can tell which lighthouse they see"],"answer":"so sailors can tell which lighthouse they see"},{"question":"What is the passage mostly about?","choices":["how lighthouses have helped keep sailors safe","why satellites are better than ships","how glass is made","how to become a sailor"],"answer":"how lighthouses have helped keep sailors safe"}]},{"text":"In 1860, sending a letter from Missouri to California could take weeks. The Pony Express promised to do it in about ten days. Young riders each galloped about 75 to 100 miles, switching to fresh horses at relay stations spaced roughly 10 to 15 miles apart. Then they handed the mail pouch to the next rider. Riders carried little besides the mail so their horses could run as fast as possible. Although the Pony Express became legendary, it lasted only about eighteen months. In October 1861, the transcontinental telegraph was completed, and messages could cross the country in minutes. The Pony Express had suddenly become obsolete.","questions":[{"question":"In the passage, the word obsolete means?","choices":["newly built","no longer needed","extremely fast","very famous"],"answer":"no longer needed"},{"question":"Why did riders carry so little besides the mail?","choices":["so they could sleep on the way","so their horses could run as fast as possible","because the mail was very heavy","because they were young"],"answer":"so their horses could run as fast as possible"},{"question":"What caused the Pony Express to end?","choices":["The telegraph could send messages in minutes.","The horses ran away.","Riders refused to work.","California stopped getting mail."],"answer":"The telegraph could send messages in minutes."}]},{"text":"Before 1869, crossing the United States meant months by wagon or a long voyage by ship. Then two companies set out to build a railroad linking the East to the West. The Central Pacific built eastward from Sacramento, California, cutting tunnels through the steep Sierra Nevada mountains. Many of its workers were immigrants from China. The Union Pacific built westward from Omaha, Nebraska, across the plains. On May 10, 1869, the two lines met at Promontory Summit in Utah, where a golden spike was tapped into place. A trip that once took months now took about a week. The railroad transformed how people and goods moved across the country.","questions":[{"question":"In the passage, the word transformed means?","choices":["quickly forgot","slowly ended","greatly changed","carefully measured"],"answer":"greatly changed"},{"question":"Where did the two railroad lines meet?","choices":["Omaha in Nebraska","Sacramento in California","Promontory Summit in Utah","the top of the Sierra Nevada"],"answer":"Promontory Summit in Utah"},{"question":"What is the main idea of the passage?","choices":["Most railroad workers lived in Utah.","The transcontinental railroad made cross-country travel much faster.","Wagons were faster than trains.","Golden spikes were used on every railroad."],"answer":"The transcontinental railroad made cross-country travel much faster."}]},{"text":"In the early 1800s, a girl named Mary Anning searched the crumbling cliffs near Lyme Regis, England, for fossils. Her family was poor, and they sold the fossils to visitors. When Mary was about twelve, she and her brother uncovered the skeleton of an ichthyosaur, a sea reptile that looked a bit like a dolphin. Later she found the first complete plesiosaur, a long-necked sea reptile. Because Mary was a woman with little schooling, scientists of her time rarely gave her credit. Yet experts traveled to learn from her, and her discoveries helped show that many kinds of animals had gone extinct long ago. Today she is celebrated as a pioneer of paleontology, the study of fossils.","questions":[{"question":"In the passage, the word pioneer means?","choices":["a person who sells fossils","a student who skips school","a type of sea reptile","one of the first to do something"],"answer":"one of the first to do something"},{"question":"What did Mary's discoveries help show?","choices":["that many kinds of animals had gone extinct","that cliffs never change","that dolphins are reptiles","that fossils are worthless"],"answer":"that many kinds of animals had gone extinct"},{"question":"What can you infer about Mary Anning?","choices":["She studied at a large university.","She was skilled and determined despite unfair treatment.","She was given many awards in her lifetime.","She did not enjoy being outdoors."],"answer":"She was skilled and determined despite unfair treatment."}]},{"text":"On some winter nights in the far north, the sky glows with ribbons of green, pink, and violet light. This display is called the aurora borealis, or northern lights. It begins with the sun, which constantly releases a stream of charged particles called the solar wind. When these particles reach Earth, our planet's magnetic field guides many of them toward the poles. There, they collide with gases high in the atmosphere, making the gases glow. Oxygen usually gives off green light, while nitrogen can produce blue or purple. A similar display near the South Pole is called the aurora australis, or southern lights.","questions":[{"question":"In the passage, the word collide means?","choices":["crash into each other","change color","float away","slowly cool down"],"answer":"crash into each other"},{"question":"Why do auroras appear mostly near the poles?","choices":["Snow at the poles reflects light.","The sun is closer to the poles.","The poles are the coldest places.","Earth's magnetic field guides particles toward the poles."],"answer":"Earth's magnetic field guides particles toward the poles."},{"question":"Which gas usually gives off green light?","choices":["smoke","nitrogen","oxygen","water vapor"],"answer":"oxygen"}]},{"text":"If you spend a day at the ocean, you may notice the water creeping up the beach and then pulling back. These daily changes in sea level are called tides. They are caused mainly by the moon's gravity. As Earth spins, the moon pulls on the oceans, creating a bulge of water on the side facing the moon and another bulge on the opposite side. Most beaches pass through both bulges each day, so they usually have two high tides and two low tides in a little more than 24 hours. The sun's gravity affects tides too. When the sun and moon line up, high tides are extra high and low tides are extra low.","questions":[{"question":"In the passage, the word bulge means?","choices":["a deep hole","a strong wind","a sandy beach","a swelling or rounded lump"],"answer":"a swelling or rounded lump"},{"question":"What mainly causes tides?","choices":["strong winds","whales swimming","rainstorms","the moon's gravity"],"answer":"the moon's gravity"},{"question":"How many high tides do most beaches have each day?","choices":["none","two","four","one"],"answer":"two"}],"photo":"images/flashcards/moon.jpg"},{"text":"Mushrooms might look like plants, but they belong to a separate group of living things called fungi. Unlike plants, fungi cannot make their own food from sunlight. Instead, many fungi are decomposers. They break down dead leaves, fallen logs, and other once-living material, returning nutrients to the soil so new plants can grow. The mushroom we see is only a small part of the fungus. Beneath the ground spreads a huge web of thin threads called mycelium. Without decomposers, forests would be buried under piles of dead plants.","questions":[{"question":"In the passage, the word decomposers means?","choices":["plants that need lots of sunlight","living things that break down dead material","animals that eat mushrooms","tools used to cut logs"],"answer":"living things that break down dead material"},{"question":"What is mycelium?","choices":["a web of thin threads underground","the cap of a mushroom","a type of leaf","a kind of rock"],"answer":"a web of thin threads underground"},{"question":"Why are fungi important to forests?","choices":["They return nutrients to the soil.","They make trees grow overnight.","They make food from sunlight.","They scare away animals."],"answer":"They return nutrients to the soil."}]},{"text":"Earthworms may seem like simple creatures, but gardeners consider them valuable helpers. As earthworms tunnel through the ground, they loosen the soil, making spaces for air and water to reach plant roots. They also eat dead leaves and bits of soil. What passes through their bodies comes out as castings, a material rich in the nutrients plants need. Earthworms have no eyes, but special cells in their skin sense light. They also breathe through their skin, which must stay moist. That is why worms stay in damp places, since dry skin would make breathing impossible.","questions":[{"question":"In the passage, the word castings means?","choices":["piles of dead leaves","nutrient-rich waste left by worms","holes that worms dig","hooks used for fishing"],"answer":"nutrient-rich waste left by worms"},{"question":"How do earthworms breathe?","choices":["through their moist skin","through a nose","through their eyes","through gills"],"answer":"through their moist skin"},{"question":"What is the main idea of the passage?","choices":["Worms can see very well.","Gardeners should remove all worms.","Earthworms harm gardens.","Earthworms help keep soil healthy for plants."],"answer":"Earthworms help keep soil healthy for plants."}]},{"text":"When winter arrives and food grows scarce, some animals survive by hibernating. Hibernation is much deeper than ordinary sleep. A woodchuck, also called a groundhog, curls up in its burrow, and its heartbeat drops from about eighty beats a minute to just a few. Its body temperature falls close to that of the burrow. By slowing down, the woodchuck uses so little energy that the fat it stored during summer and fall can last until spring. Bears are often called hibernators, but their body temperature drops only a little, and they can wake more easily. Either way, these strategies help animals survive the hungry months.","questions":[{"question":"In the passage, the word scarce means?","choices":["easy to reach","very tasty","hard to find","frozen solid"],"answer":"hard to find"},{"question":"How does hibernating help a woodchuck survive?","choices":["It grows thicker fur.","It eats more food in winter.","It uses very little energy, so its fat lasts.","It flies south for the winter."],"answer":"It uses very little energy, so its fat lasts."},{"question":"How is a bear's winter rest different from a woodchuck's?","choices":["A bear rests only in summer.","A bear's body temperature drops only a little.","A bear does not rest at all.","A bear's heart stops completely."],"answer":"A bear's body temperature drops only a little."}]},{"text":"A tornado is a violently spinning column of air that stretches from a thunderstorm down to the ground. Many tornadoes form in powerful storms called supercells, where warm, moist air near the ground meets cooler, drier air above. The United States has more tornadoes than any other country, especially in an area of the central plains nicknamed Tornado Alley. Meteorologists use radar to spot rotation inside storms and issue warnings. When a tornado warning is announced, people should move to a basement or to an interior room without windows on the lowest floor. Planning ahead and practicing drills can save lives.","questions":[{"question":"In the passage, the word interior means?","choices":["inside","outdoor","broken","upstairs"],"answer":"inside"},{"question":"What tool do meteorologists use to spot rotation in storms?","choices":["a thermometer","a telescope","a compass","radar"],"answer":"radar"},{"question":"Where is the safest place to go during a tornado warning?","choices":["a basement or windowless inside room","a car on the highway","the top floor of a building","a room with large windows"],"answer":"a basement or windowless inside room"}]},{"text":"Have you ever wondered why bread is fluffy instead of flat? The secret is yeast, a tiny living fungus. When a baker mixes yeast with flour, water, and a little sugar, the yeast begins to feed on the sugars. As it eats, it releases a gas called carbon dioxide. Stretchy strands of gluten, a protein in wheat flour, trap the gas in thousands of tiny bubbles, causing the dough to rise. When the bread bakes, the heat sets the bubbles in place, leaving the soft, airy holes you see in a slice. Without yeast, the loaf would bake into a dense, heavy brick.","questions":[{"question":"In the passage, the word releases means?","choices":["freezes","hides","swallows","lets out"],"answer":"lets out"},{"question":"What traps the gas in tiny bubbles?","choices":["grains of salt","strands of gluten","drops of oil","pieces of sugar"],"answer":"strands of gluten"},{"question":"What would happen to this bread if it were made without yeast?","choices":["It would be dense and heavy.","It would be extra fluffy.","It would turn green.","It would float away."],"answer":"It would be dense and heavy."}],"photo":"images/flashcards/bread.jpg"},{"text":"Every popcorn kernel holds a tiny surprise: a small drop of water stored inside a ring of soft starch. The kernel's hard outer shell, called the hull, keeps that moisture sealed in. When the kernel is heated to about 350 degrees Fahrenheit, the water turns to steam. Pressure builds up inside until the hull suddenly bursts. The hot starch puffs out and cools almost instantly into the white, fluffy shape we eat. Kernels that do not pop often have cracked hulls or too little moisture, so the steam escapes before enough pressure can build.","questions":[{"question":"In the passage, the word hull means?","choices":["the hard outer shell of a kernel","a drop of water","the fluffy white part","a cooking pot"],"answer":"the hard outer shell of a kernel"},{"question":"What causes the kernel to burst?","choices":["cold air","salt on the outside","a sharp knife","pressure from steam inside"],"answer":"pressure from steam inside"},{"question":"Why might some kernels not pop?","choices":["They are the wrong color.","They are too fluffy.","They have too much starch.","Their hulls are cracked or they lack moisture."],"answer":"Their hulls are cracked or they lack moisture."}]},{"text":"A magnet has two ends called poles: a north pole and a south pole. Opposite poles attract, pulling toward each other, while like poles repel, pushing apart. Earth itself behaves like a giant magnet, and that is why a compass works. Its needle is a small magnet that can spin freely, and it lines up with Earth's magnetic field so one end points north. For about a thousand years, sailors and travelers have relied on compasses to find their way, even on cloudy nights when they could not see the stars. Early compasses, first used in China, were made with a naturally magnetic stone called lodestone.","questions":[{"question":"In the passage, the word repel means?","choices":["push away","break apart","spin around","pull close"],"answer":"push away"},{"question":"Why does a compass needle point north?","choices":["The stars pull on it.","It lines up with Earth's magnetic field.","One end is heavier.","The wind pushes it."],"answer":"It lines up with Earth's magnetic field."},{"question":"What was lodestone?","choices":["a naturally magnetic stone","a star used for travel","a tool for measuring depth","a kind of map"],"answer":"a naturally magnetic stone"}]},{"text":"Plants cannot walk, yet their seeds manage to travel surprisingly far. Spreading seeds away from the parent plant, called dispersal, gives young plants room, light, and water of their own. Plants have developed clever methods. Dandelion seeds ride the wind on tiny parachutes, and maple seeds spin like helicopter blades. Coconuts can float across the ocean for weeks. Burrs have hooks that cling to animal fur and hikers' socks. Many plants wrap seeds in tasty fruit; animals eat the fruit and later drop the seeds far away. Some plants, like touch-me-nots, even fling their seeds by bursting their pods.","questions":[{"question":"In the passage, the word dispersal means?","choices":["the eating of fruit","the falling of leaves","the growing of roots","the spreading out of seeds"],"answer":"the spreading out of seeds"},{"question":"Why is it helpful for seeds to travel away from the parent plant?","choices":["Seeds need to see new places.","Young plants get their own room, light, and water.","Animals need seeds to grow fur.","The parent plant needs more shade."],"answer":"Young plants get their own room, light, and water."},{"question":"How do burrs travel?","choices":["by spinning in the wind","by bursting from pods","by floating on the ocean","by clinging to animal fur"],"answer":"by clinging to animal fur"}],"photo":"images/flashcards/plant.jpg"},{"text":"The axolotl is a salamander found in the wild only in a few lakes and canals near Mexico City. Unlike most salamanders, which move onto land as adults, axolotls usually stay in the water their whole lives, keeping feathery gills that stick out from the sides of their heads. Their most amazing ability is regeneration. If an axolotl loses a leg, it can grow back a complete new one, including bones, muscles, and nerves. Scientists study axolotls hoping to learn more about healing. Sadly, wild axolotls are critically endangered because of pollution and the loss of their habitat, so people are working to protect the canals where they live.","questions":[{"question":"In the passage, the word regeneration means?","choices":["laying eggs","swimming fast","regrowing lost body parts","changing color"],"answer":"regrowing lost body parts"},{"question":"Why are wild axolotls endangered?","choices":["pollution and loss of habitat","very cold winters","a lack of sunlight","too many predators on land"],"answer":"pollution and loss of habitat"},{"question":"How are axolotls different from most salamanders?","choices":["They usually stay in the water as adults.","They have no legs.","They live high in trees.","They can fly short distances."],"answer":"They usually stay in the water as adults."}]},{"text":"Along the Pacific coast, sea otters play a surprisingly important role in underwater forests of giant kelp. Sea urchins, spiny creatures that graze on kelp, can multiply quickly and chew through entire forests, leaving bare areas called urchin barrens. Sea otters love to eat urchins, cracking them open while floating on their backs. By keeping the number of urchins in check, otters allow kelp forests to thrive. Those forests, in turn, shelter fish, seals, and countless other creatures. Because one species has such a large effect on its whole community, scientists call the sea otter a keystone species, named after the central stone that holds an arch together.","questions":[{"question":"In the passage, the word thrive means?","choices":["disappear","sink to the bottom","grow strong and healthy","become spiny"],"answer":"grow strong and healthy"},{"question":"What happens when there are too many sea urchins?","choices":["Fish find more places to hide.","They chew through kelp forests.","Sea otters grow bigger.","The water gets warmer."],"answer":"They chew through kelp forests."},{"question":"Why is the sea otter called a keystone species?","choices":["It is the largest animal in the ocean.","It builds stone arches.","It lives near rocky shores.","It has a large effect on its whole community."],"answer":"It has a large effect on its whole community."}]},{"text":"For decades, Major League Baseball was segregated. Black players were kept out and had to play in separate leagues called the Negro Leagues. That changed on April 15, 1947, when Jackie Robinson took the field for the Brooklyn Dodgers. Some fans and players shouted insults at him, and he received threatening letters. Robinson had promised not to fight back in anger, so he answered with his skill. He hit well, stole bases boldly, and was named Rookie of the Year. His courage opened the door for other Black athletes. Today, every April 15, all major league players wear his number, 42, to honor him.","questions":[{"question":"In the passage, the word segregated means?","choices":["separated by race","sold out","played only at night","very popular"],"answer":"separated by race"},{"question":"How did Jackie Robinson respond to insults?","choices":["He answered with his skill instead of fighting.","He shouted back.","He quit the team.","He switched to another sport."],"answer":"He answered with his skill instead of fighting."},{"question":"Why do players wear number 42 every April 15?","choices":["because the Dodgers won 42 games","to honor Jackie Robinson","to celebrate spring","because it is a lucky number"],"answer":"to honor Jackie Robinson"}]},{"text":"In 1804, President Thomas Jefferson sent Meriwether Lewis and William Clark to explore the vast lands west of the Mississippi River. Their group, called the Corps of Discovery, traveled by boat, on foot, and on horseback. They mapped rivers, recorded many plants and animals that were new to them, and met many Native American nations. A Shoshone woman named Sacagawea joined the journey as an interpreter, carrying her baby son along the way. Her presence showed others that the group came in peace, and she helped them get horses to cross the Rocky Mountains. In November 1805, the explorers reached the Pacific Ocean.","questions":[{"question":"In the passage, the word interpreter means?","choices":["a person who draws maps","a boat captain","a cook for the group","someone who translates between languages"],"answer":"someone who translates between languages"},{"question":"How did Sacagawea help the expedition?","choices":["She translated and helped them get horses.","She drew every map.","She paid for the trip.","She steered all the boats."],"answer":"She translated and helped them get horses."},{"question":"What did the explorers reach in November 1805?","choices":["the Atlantic Ocean","the Mississippi River","the Gulf of Mexico","the Pacific Ocean"],"answer":"the Pacific Ocean"}],"photo":"images/flashcards/boat.jpg"},{"text":"The Amazon rainforest covers much of northern South America and is the largest tropical rainforest on Earth. It is home to an astonishing variety of life, including jaguars, sloths, poison dart frogs, and huge numbers of insects. Scientists estimate that roughly one in ten known species on the planet lives there. The forest is layered like a building. Tall emergent trees poke above a thick canopy, where most of the animals live, while the dim forest floor below receives little sunlight. The Amazon also matters to the whole planet, since its trees absorb carbon dioxide and release moisture that helps form rain clouds.","questions":[{"question":"In the passage, the word astonishing means?","choices":["slightly scary","quite small","very surprising","very boring"],"answer":"very surprising"},{"question":"Where do most of the rainforest's animals live?","choices":["in the canopy","on the forest floor","in the river","above the emergent trees"],"answer":"in the canopy"},{"question":"What is the main idea of the passage?","choices":["Sloths are the most important rainforest animal.","The Amazon is a huge, layered rainforest full of life.","Rain clouds form only over oceans.","The forest floor gets lots of sunlight."],"answer":"The Amazon is a huge, layered rainforest full of life."}]},{"text":"Mount Everest, on the border between Nepal and China, is the highest mountain above sea level, rising about 29,032 feet. Near its summit, the air holds only about one third of the oxygen found at sea level, so most climbers carry bottled oxygen. Fierce winds, freezing temperatures, and deep cracks in the ice called crevasses make the climb dangerous. On May 29, 1953, Edmund Hillary of New Zealand and Tenzing Norgay, a Sherpa mountaineer, became the first people confirmed to reach the top. They climbed as a team, and both men later said the success belonged to them together.","questions":[{"question":"In the passage, the word summit means?","choices":["the bottom of a valley","a deep crack in ice","a kind of tent","the highest point of a mountain"],"answer":"the highest point of a mountain"},{"question":"Why do most climbers carry bottled oxygen?","choices":["The air near the top has much less oxygen.","It helps them see crevasses.","It makes their packs lighter.","The oxygen keeps them warm."],"answer":"The air near the top has much less oxygen."},{"question":"What can you infer about Hillary and Tenzing?","choices":["They climbed alone.","They disliked each other.","They valued teamwork.","They were racing each other."],"answer":"They valued teamwork."}]},{"text":"When Imani noticed that her neighbors each owned a ladder but rarely used it, she had an idea. Why should every family buy the same tools when they could share? With her mom's help, Imani turned an empty shed at the community center into a tool library. Neighbors donated rakes, drills, wheelbarrows, and even a pressure washer. Anyone could borrow a tool for a week, just like a library book. At first, only a few people stopped by. But after Mr. Okafor used a borrowed ladder to fix his roof and told everyone about it, the sign-up sheet filled quickly. By spring, the tool library had saved the neighborhood hundreds of dollars.","questions":[{"question":"In the passage, the word donated means?","choices":["broke on purpose","gave as a gift","sold for money","borrowed for a week"],"answer":"gave as a gift"},{"question":"What helped the tool library become popular?","choices":["The tools were given away forever.","Imani hung posters at school.","Mr. Okafor told everyone how it helped him.","The city paid people to visit."],"answer":"Mr. Okafor told everyone how it helped him."},{"question":"What is the main lesson of the story?","choices":["Libraries should only hold books.","Every family should own every tool.","Sharing resources can benefit a whole community.","Ladders are too dangerous to use."],"answer":"Sharing resources can benefit a whole community."}]},{"text":"Rafael had practiced for the school spelling bee for weeks, but as he waited backstage, his hands felt clammy and his mind went blank. His best friend Dev, who had been knocked out in the first round, slipped him a note. It read, 'You already know these words. Just picture our kitchen-table practice.' Rafael took a slow breath and imagined Dev quizzing him over bowls of cereal. When his turn came, he spelled 'nocturnal' correctly, then 'perimeter,' then 'gracious.' He finished in second place. Afterward, Rafael handed Dev the ribbon. 'Half of this is yours,' he said.","questions":[{"question":"In the passage, the word clammy means?","choices":["warm and dry","strong and steady","damp and cold","rough and scratchy"],"answer":"damp and cold"},{"question":"How did Dev help Rafael?","choices":["He reminded him of their practice sessions.","He asked the judges to go easy.","He spelled the words for him.","He gave him a dictionary."],"answer":"He reminded him of their practice sessions."},{"question":"Why did Rafael say 'Half of this is yours'?","choices":["He did not like the ribbon.","Dev had also won second place.","The judges told him to share it.","He believed Dev's help made his success possible."],"answer":"He believed Dev's help made his success possible."}]},{"text":"Because sending people to Mars is extremely difficult, scientists have explored the planet with robotic rovers. These wheeled vehicles, the newest about the size of a car, carry cameras, drills, and instruments that analyze rocks and soil. Radio signals take between about 3 and 22 minutes to travel from Earth to Mars, so engineers cannot steer a rover like a remote-control car. Instead, they send a list of instructions, and the rover carries them out on its own. Rovers have found evidence that Mars once had lakes and rivers, raising the question of whether tiny living things might once have existed there.","questions":[{"question":"In the passage, the word analyze means?","choices":["paint","bury","study closely","throw away"],"answer":"study closely"},{"question":"Why can't engineers steer a rover like a remote-control car?","choices":["Mars has no roads.","The rovers have no wheels.","The engineers live on Mars.","Radio signals take minutes to travel between planets."],"answer":"Radio signals take minutes to travel between planets."},{"question":"What evidence have rovers found?","choices":["that Mars once had lakes and rivers","that people once lived on Mars","that Mars has forests","that Mars is made of ice"],"answer":"that Mars once had lakes and rivers"}]}]},"synonyms":{"easy":{"toss":"throw","sniff":"smell","damp":"moist","quick":"speedy","sob":"weep","tug":"pull","chat":"talk","nap":"doze"},"hard":{"ponder":"consider","feeble":"weak","elated":"overjoyed","prudent":"sensible","lucid":"clear","jovial":"merry","dubious":"doubtful"}},"antonyms":{"easy":{"sunny":"cloudy","lose":"find","never":"always","before":"after","even":"odd","hello":"goodbye","few":"many","catch":"throw"},"hard":{"inhale":"exhale","ally":"enemy","frequent":"seldom","artificial":"natural","import":"export","drought":"flood","despair":"hope"}},"rhymes":{"easy":[["duck","truck","luck","stuck","tuck"],["peach","beach","reach","teach","each"],["pink","sink","wink","drink","think"],["corn","horn","born","worn","torn"]],"hard":[["kitten","mitten","bitten","smitten","written"],["rocket","pocket","socket","locket"],["giggle","wiggle","jiggle","squiggle"],["flutter","butter","clutter","gutter","shutter"]]},"analogies":[["glove","hand","boot","foot"],["painter","brush","writer","pen"],["puppy","dog","calf","cow"],["thermometer","temperature","ruler","length"],["bread","bakery","medicine","pharmacy"],["wool","sheep","honey","bee"],["chapter","book","verse","song"],["oar","rowboat","pedal","bicycle"]]},{"id":"2026-10-18-weekly-reading","released":"2026-10-18","kind":"weekly","reading_passages":{"0":[{"text":"A ladybug sits on a green leaf. She has red wings with black spots. She eats tiny bugs. Then she flies away.","questions":[{"question":"What color are the ladybug's wings?","choices":["red","blue","pink","white"],"answer":"red"},{"question":"Where does the ladybug sit?","choices":["on a leaf","on a rock","on a hat","on a cake"],"answer":"on a leaf"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: A ladybug sits on a green leaf. Focus on: a red ladybug with black spots on a green leaf. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Sam puts on his yellow boots. It rained all night. He jumps in a big puddle. Splash! His socks stay dry.","questions":[{"question":"What does Sam put on?","choices":["boots","mittens","a hat","a scarf"],"answer":"boots"},{"question":"Where does Sam jump?","choices":["in a puddle","in a pool","in the sand","on the bed"],"answer":"in a puddle"},{"question":"How do his socks stay?","choices":["dry","wet","cold","muddy"],"answer":"dry"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Sam puts on his yellow boots. Focus on: a boy in yellow rain boots splashing in a puddle. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Grandpa and Lily bake muffins. They mix flour, eggs, and blueberries. The oven gets hot. Soon the kitchen smells sweet.","questions":[{"question":"What do Grandpa and Lily bake?","choices":["muffins","cookies","pancakes","bread"],"answer":"muffins"},{"question":"What fruit goes in the muffins?","choices":["blueberries","bananas","apples","cherries"],"answer":"blueberries"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Grandpa and Lily bake muffins. Focus on: a grandpa and girl baking blueberry muffins. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"The turtle walks very slowly. He carries his shell on his back. When he is scared, he hides his head inside.","questions":[{"question":"How does the turtle walk?","choices":["slowly","fast","backward","sideways"],"answer":"slowly"},{"question":"What does he carry on his back?","choices":["his shell","a bag","a big leaf","a small box"],"answer":"his shell"},{"question":"What does he hide when he is scared?","choices":["his head","his tail","his toys","his food"],"answer":"his head"}]},{"text":"Mia blows bubbles at the park. The bubbles are round and shiny. One lands on her nose. Pop!","questions":[{"question":"Where does Mia blow bubbles?","choices":["at the park","at school","at the beach","in the car"],"answer":"at the park"},{"question":"Where does one bubble land?","choices":["on her nose","on her hand","on a dog","on a tree"],"answer":"on her nose"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Mia blows bubbles at the park. Focus on: a girl blowing shiny bubbles in a park. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Ben has six crayons. Ava has none. Ben gives Ava three crayons. Now they can both draw. Ava says thank you.","questions":[{"question":"How many crayons does Ben have at first?","choices":["six","three","two","ten"],"answer":"six"},{"question":"What does Ava say?","choices":["thank you","good night","hello","no thanks"],"answer":"thank you"}]},{"text":"The fire truck is big and red. It has a long ladder and a loud siren. Firefighters ride in it to help people.","questions":[{"question":"What color is the fire truck?","choices":["red","green","orange","white"],"answer":"red"},{"question":"What does the fire truck have?","choices":["a long ladder","a big slide","a tall mast","a soft bed"],"answer":"a long ladder"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: The fire truck is big and red. Focus on: a red fire truck with a long ladder. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"At night the moon comes out. It looks like a big silver ball. Stars twinkle all around it. Owls hoot in the trees.","questions":[{"question":"When does the moon come out?","choices":["at night","at lunch","in the morning","after school"],"answer":"at night"},{"question":"What hoots in the trees?","choices":["owls","dogs","frogs","ducks"],"answer":"owls"}],"photo":"images/flashcards/moon.jpg"},{"text":"Kai and Zoe build a snowman. They roll three big snowballs. They add a carrot nose and two button eyes. Brr, it is cold!","questions":[{"question":"How many snowballs do they roll?","choices":["three","seven","four","two"],"answer":"three"},{"question":"What is the snowman's nose?","choices":["a carrot","a button","a stick","a rock"],"answer":"a carrot"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Kai and Zoe build a snowman. Focus on: two kids building a snowman with a carrot nose. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Goldie is a little orange fish. She swims in a round bowl. Every morning Max feeds her. She swims up to eat.","questions":[{"question":"What color is Goldie?","choices":["orange","purple","brown","gray"],"answer":"orange"},{"question":"Who feeds Goldie?","choices":["Max","Mom","Grandma","the cat"],"answer":"Max"},{"question":"When does Max feed her?","choices":["every morning","every night","at lunch","on Sunday"],"answer":"every morning"}],"photo":"images/flashcards/fish.jpg"},{"text":"Dad plants a tiny seed in the dirt. Nora waters it every day. The sun shines on it. One day a green sprout pops up!","questions":[{"question":"What does Dad plant?","choices":["a seed","a tree","a rock","a coin"],"answer":"a seed"},{"question":"Who waters the seed?","choices":["Nora","Dad","the dog","Grandma"],"answer":"Nora"},{"question":"What pops up?","choices":["a green sprout","a red apple","a yellow duck","a small worm"],"answer":"a green sprout"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Dad plants a tiny seed in the dirt. Focus on: a green sprout growing from dirt. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"The bus stops at the corner. Rosa climbs the steps. She sits by the window and waves to her mom. The bus goes to school.","questions":[{"question":"Where does Rosa sit?","choices":["by the window","in the back","by the driver","on the floor"],"answer":"by the window"},{"question":"Where does the bus go?","choices":["to school","to the zoo","to the store","to the farm"],"answer":"to school"}],"photo":"images/flashcards/bus.jpg"},{"text":"A puppy named Biscuit loves to dig. He digs in the yard and finds an old bone. He wags his tail and runs inside.","questions":[{"question":"What does Biscuit love to do?","choices":["dig","swim","sleep","bark"],"answer":"dig"},{"question":"What does Biscuit find?","choices":["an old bone","a red ball","a toy car","a lost shoe"],"answer":"an old bone"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: A puppy named Biscuit loves to dig. Focus on: a puppy digging up a bone in a yard. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Lemons are yellow and sour. Ella squeezes lemons into water. She adds a little sugar. Now she has lemonade to share.","questions":[{"question":"How do lemons taste?","choices":["sour","sweet","salty","spicy"],"answer":"sour"},{"question":"What does Ella add to the water?","choices":["sugar","salt","milk","ice cream"],"answer":"sugar"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Lemons are yellow and sour. Focus on: a girl making lemonade with lemons. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Leo feels sad. His tower of blocks fell down. His sister helps him build it again. Now the tower is tall, and Leo smiles.","questions":[{"question":"Why is Leo sad?","choices":["his tower fell","he lost his hat","his dog ran off","it is raining"],"answer":"his tower fell"},{"question":"Who helps Leo?","choices":["his sister","his dad","his friend","his teacher"],"answer":"his sister"}]},{"text":"A squirrel finds acorns in the fall. She hides them in the ground. When winter comes, she digs them up to eat.","questions":[{"question":"What does the squirrel find?","choices":["acorns","apples","berries","pinecones"],"answer":"acorns"},{"question":"When does she dig them up?","choices":["in winter","in summer","at lunch","on her birthday"],"answer":"in winter"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: A squirrel finds acorns in the fall. Focus on: a squirrel burying acorns in fall. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Ana rides her bike with her helmet on. She rings her bell, ding, ding! She rides slowly past the ducks at the pond.","questions":[{"question":"What does Ana wear?","choices":["a helmet","a crown","a cape","a mask"],"answer":"a helmet"},{"question":"What does Ana ride past?","choices":["the ducks","the cows","the trains","the horses"],"answer":"the ducks"}]},{"text":"The farmer milks the cow in the barn. The cow says moo. The milk goes in a big pail. The cat waits for a drink.","questions":[{"question":"Where is the cow?","choices":["in the barn","in the house","at the park","in a boat"],"answer":"in the barn"},{"question":"Who waits for a drink?","choices":["the cat","the pig","the horse","the farmer"],"answer":"the cat"}],"photo":"images/flashcards/cow.jpg"},{"text":"It is windy today. The leaves blow off the trees. Red, orange, and brown leaves fall. Jack jumps into a big leaf pile.","questions":[{"question":"What kind of day is it?","choices":["windy","snowy","sunny and hot","foggy"],"answer":"windy"},{"question":"What does Jack jump into?","choices":["a leaf pile","a pool","a sandbox","a puddle"],"answer":"a leaf pile"}],"photo":"images/flashcards/leaf.jpg"},{"text":"Ruby has a new toothbrush. She brushes her teeth in the morning and at night. She brushes for two whole minutes. Her teeth are clean.","questions":[{"question":"When does Ruby brush her teeth?","choices":["morning and night","only after lunch","only before naps","on Saturdays only"],"answer":"morning and night"},{"question":"How long does Ruby brush?","choices":["two minutes","ten minutes","one hour","five seconds"],"answer":"two minutes"}]}],"1":[{"text":"Hummingbirds are the smallest birds. Their wings beat so fast that they make a humming sound. They can even fly backward! Hummingbirds drink nectar from flowers with their long, thin beaks. Because they use so much energy, they must eat many times every day.","questions":[{"question":"Why do hummingbirds make a humming sound?","choices":["their wings beat fast","they sing loud songs","they hum to their babies","their beaks whistle"],"answer":"their wings beat fast"},{"question":"What can hummingbirds do?","choices":["fly backward","swim underwater","sleep upside down","walk on water"],"answer":"fly backward"},{"question":"What do hummingbirds drink?","choices":["nectar","milk","rainwater","juice"],"answer":"nectar"}]},{"text":"Omar could not find his library book. He looked under his bed and in his backpack. Then he remembered reading in the car. He ran outside and found the book on the back seat. He returned it to the library right on time.","questions":[{"question":"Where did Omar find the book?","choices":["on the back seat","under his bed","in his backpack","on the kitchen table"],"answer":"on the back seat"},{"question":"What did Omar remember?","choices":["reading in the car","reading at school","leaving it at Grandma's","giving it to a friend"],"answer":"reading in the car"}],"photo":"images/flashcards/book.jpg"},{"text":"Fog is a cloud that sits close to the ground. It forms when warm, wet air cools down. On foggy mornings, it can be hard to see far away. Drivers turn on their lights and go slowly. When the sun warms the air, the fog goes away.","questions":[{"question":"What is fog?","choices":["a cloud near the ground","smoke from a big campfire","melted snow on the road","dust blown by the wind"],"answer":"a cloud near the ground"},{"question":"What do drivers do in fog?","choices":["turn on their lights","honk their horns","stop for lunch","open their windows"],"answer":"turn on their lights"},{"question":"What makes the fog go away?","choices":["the sun warming the air","a heavy rain falling down","the cars driving past it","the birds flapping wings"],"answer":"the sun warming the air"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Fog is a cloud that sits close to the ground. Focus on: a foggy morning street with cars using headlights. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Long ago, in 1891, a teacher named James Naismith wanted a game his students could play indoors in winter. He nailed two peach baskets high on the walls. Players tried to toss a ball into the baskets. That was the very first game of basketball!","questions":[{"question":"What did James Naismith use for the first hoops?","choices":["peach baskets","metal buckets","cardboard boxes","plastic hoops"],"answer":"peach baskets"},{"question":"Why did he make up the game?","choices":["to play indoors in winter","to win a big trophy prize","to sell his peach baskets","to have fun at the beach"],"answer":"to play indoors in winter"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Long ago, in 1891, a teacher named James Naismith wanted a game his students could play indoors in winter. Focus on: students tossing a ball into peach baskets in an old gym. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Maple syrup comes from maple trees. In early spring, farmers make a small hole in the tree trunk. Clear, watery sap drips out into a bucket. The farmers boil the sap for a long time. The water goes away, and sweet, sticky syrup is left.","questions":[{"question":"When do farmers collect the sap?","choices":["early spring","late summer","winter nights","fall"],"answer":"early spring"},{"question":"What do the farmers do to the sap?","choices":["boil it","freeze it","drink it","paint it"],"answer":"boil it"},{"question":"What does the sap look like?","choices":["clear and watery","brown and sticky","red and thick","white and fluffy"],"answer":"clear and watery"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Maple syrup comes from maple trees. Focus on: maple sap dripping into a bucket on a tree. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"A new girl named Priya joined Mr. Lee's class. She sat alone at lunch. Carlos noticed and invited her to sit with his friends. Priya told them about her old school. By the end of lunch, everyone was laughing together.","questions":[{"question":"Where did Priya sit at first?","choices":["alone at lunch","with Carlos","next to the teacher","on the playground"],"answer":"alone at lunch"},{"question":"What did Carlos do?","choices":["invited her to sit with friends","showed her the library books","gave her a new pencil box","walked her to the art room after lunch"],"answer":"invited her to sit with friends"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: A new girl named Priya joined Mr. Focus on: children welcoming a new girl at a lunch table. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Sea turtles spend most of their lives in the ocean. But a mother sea turtle crawls onto a sandy beach to lay her eggs. She digs a hole and covers the eggs with sand. Weeks later, tiny baby turtles hatch and hurry to the water.","questions":[{"question":"Where does the mother lay her eggs?","choices":["on a sandy beach","in a coral reef","on a floating log","in a tall tree"],"answer":"on a sandy beach"},{"question":"What do the babies do after they hatch?","choices":["hurry to the water","dig a deeper hole","sleep in the sand","wait for their mother"],"answer":"hurry to the water"}]},{"text":"Jada wanted to know how much rain fell. She put an empty jar outside in the yard. After a rainy night, she used a ruler to measure the water in the jar. It was two inches deep! She wrote the number in her weather notebook.","questions":[{"question":"What did Jada use to measure the water?","choices":["a ruler","a cup","a scale","a clock"],"answer":"a ruler"},{"question":"How deep was the water?","choices":["two inches","ten inches","one foot","half an inch"],"answer":"two inches"},{"question":"Where did Jada write the number?","choices":["in her weather notebook","on the kitchen wall","on the empty jar lid","in a letter to Grandma"],"answer":"in her weather notebook"}],"photo":"images/flashcards/rain.jpg"},{"text":"Every school morning, Mr. Brooks stands at the busy corner in a bright orange vest. He is the crossing guard. He holds up a red stop sign so cars will stop. Then he helps the children cross the street safely.","questions":[{"question":"What color is Mr. Brooks's vest?","choices":["orange","green","blue","yellow"],"answer":"orange"},{"question":"What does Mr. Brooks hold up?","choices":["a red stop sign","a big umbrella","a yellow flag","a bright flashlight"],"answer":"a red stop sign"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Every school morning, Mr. Focus on: a crossing guard in an orange vest holding a stop sign. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Saturn is the sixth planet from the sun. It is famous for its beautiful rings. The rings are made of billions of pieces of ice and rock. Some pieces are as small as sand, and some are as big as a house. Saturn is so far away that one year there lasts about 29 Earth years.","questions":[{"question":"What are Saturn's rings made of?","choices":["ice and rock","gas and fire","sand and water","dust and leaves"],"answer":"ice and rock"},{"question":"How long is one year on Saturn?","choices":["about 29 Earth years","about one Earth year","about 6 Earth years","about 100 Earth days"],"answer":"about 29 Earth years"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Saturn is the sixth planet from the sun. Focus on: the planet Saturn and its rings. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Hannah's hands shook before her piano recital. Her stomach felt full of butterflies. Her teacher told her to take three deep breaths. Hannah breathed in and out. She felt calmer, sat down, and played her song from start to finish.","questions":[{"question":"What did Hannah's teacher tell her to do?","choices":["take three deep breaths","drink a glass of water","practice her song one more time","go home and rest"],"answer":"take three deep breaths"},{"question":"What instrument did Hannah play?","choices":["piano","violin","drum","flute"],"answer":"piano"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Hannah's hands shook before her piano recital. Focus on: a girl taking a deep breath at a piano. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Sloths live high in the trees of rainforests. They move so slowly that tiny green plants called algae grow on their fur. The green color helps sloths hide from hungry animals. Sloths climb down from their tree only about once a week.","questions":[{"question":"What grows on a sloth's fur?","choices":["algae","flowers","mushrooms","moss"],"answer":"algae"},{"question":"How does the green color help sloths?","choices":["it helps them hide","it keeps them warm","it makes them fast","it helps them swim"],"answer":"it helps them hide"},{"question":"How often do sloths climb down?","choices":["about once a week","about every hour","twice every single day","only once a year"],"answer":"about once a week"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Sloths live high in the trees of rainforests. Focus on: a sloth hanging in a rainforest tree. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"On Friday, the Garcia family makes pizza together. Dad rolls the dough into a circle. Lucia spreads tomato sauce on top. Her brother sprinkles cheese and adds peppers. Mom puts the pizza in the hot oven. Twenty minutes later, dinner is ready!","questions":[{"question":"Who spreads the tomato sauce?","choices":["Lucia","Dad","Mom","her brother"],"answer":"Lucia"},{"question":"How long does the pizza bake?","choices":["twenty minutes","five minutes","about an hour","two whole hours"],"answer":"twenty minutes"}],"photo":"images/flashcards/pizza.jpg"},{"text":"A robot vacuum cleans floors all by itself. It has sensors that work like eyes. When it bumps into a chair, it turns and goes another way. When its battery runs low, it rolls back to its charger to rest.","questions":[{"question":"What helps the robot find its way?","choices":["sensors","wheels","a map","a remote"],"answer":"sensors"},{"question":"What does the robot do when its battery is low?","choices":["rolls back to its charger","beeps loudly for help","stops in the hallway","turns off its lights"],"answer":"rolls back to its charger"}],"photo":"images/flashcards/robot.jpg"},{"text":"On Saturday, Theo and his mom helped at the animal shelter. Theo filled water bowls and brushed a fluffy gray cat. His mom walked three dogs around the block. Before they left, the gray cat purred and rubbed against Theo's leg.","questions":[{"question":"Where did Theo and his mom help?","choices":["at the animal shelter","at the library","at a pet store","at the city zoo gate"],"answer":"at the animal shelter"},{"question":"What color was the cat Theo brushed?","choices":["gray","white","black","orange"],"answer":"gray"},{"question":"How many dogs did Mom walk?","choices":["three","eight","four","two"],"answer":"three"}],"photo":"images/flashcards/cat.jpg"},{"text":"When thunder roars, go indoors! Lightning can strike tall things outside, like trees and poles. During a storm, stay inside and away from windows. Wait thirty minutes after the last thunder before you go back outside to play.","questions":[{"question":"How long should you wait after the last thunder?","choices":["thirty minutes","five minutes","one minute","two hours"],"answer":"thirty minutes"},{"question":"What can lightning strike?","choices":["tall things like trees","small flowers in the grass","only cars on the road","only puddles of water"],"answer":"tall things like trees"}]},{"text":"The Grand Canyon is a giant valley in Arizona. It is more than a mile deep! The Colorado River carved it slowly over millions of years. The rock walls have stripes of red, orange, and tan. Each stripe is a different layer of rock.","questions":[{"question":"What carved the Grand Canyon?","choices":["the Colorado River","a big earthquake","a giant moving glacier","strong desert winds"],"answer":"the Colorado River"},{"question":"What are the stripes on the canyon walls?","choices":["layers of rock","painted lines","roots of trees","water marks"],"answer":"layers of rock"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: The Grand Canyon is a giant valley in Arizona. Focus on: the striped rock walls of the Grand Canyon. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"The first time Mei went ice skating, she fell down five times. Her dad held her hand and told her to bend her knees. Mei kept trying. By the end of the day, she could skate all the way around the rink by herself.","questions":[{"question":"How many times did Mei fall?","choices":["five","two","ten","seven"],"answer":"five"},{"question":"What did her dad tell her to do?","choices":["bend her knees","skate faster","close her eyes","stand very still"],"answer":"bend her knees"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: The first time Mei went ice skating, she fell down five times. Focus on: a girl learning to ice skate holding her dad's hand. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"A hermit crab does not grow its own shell. It lives inside an empty shell that another sea animal left behind. As the crab grows bigger, its shell gets too tight. Then it looks for a larger shell and moves in.","questions":[{"question":"Where does a hermit crab live?","choices":["in an empty shell","in a sandcastle","under a big rock","inside a sea star"],"answer":"in an empty shell"},{"question":"What does the crab do when its shell is too tight?","choices":["looks for a larger shell","grows a new shell","stays inside forever","swims to the deep ocean"],"answer":"looks for a larger shell"}],"photo":"images/flashcards/crab.jpg"},{"text":"Our class cleaned up Maple Street Park. We wore gloves and picked up trash. We filled six big bags! Then we planted yellow flowers near the slide. Now the park looks bright and cheerful, and more families come to play.","questions":[{"question":"How many bags did the class fill?","choices":["six","three","nine","twelve"],"answer":"six"},{"question":"What did the class plant?","choices":["yellow flowers","small trees","green beans","pumpkins"],"answer":"yellow flowers"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Our class cleaned up Maple Street Park. Focus on: kids picking up litter and planting flowers in a park. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Every snowflake has six sides or six points. Snowflakes form high in cold clouds when tiny drops of water freeze onto specks of dust. As a snowflake falls, more ice crystals stick to it. No two snowflakes look exactly alike.","questions":[{"question":"How many sides does a snowflake have?","choices":["six","four","eight","five"],"answer":"six"},{"question":"Where do snowflakes form?","choices":["in cold clouds","on cold windows","in the ocean","inside freezers"],"answer":"in cold clouds"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Every snowflake has six sides or six points. Focus on: a close-up six-pointed snowflake. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"When Isaac bit into an apple, his front tooth wiggled loose and came out. He was not scared because it was a baby tooth. His dentist had told him a bigger adult tooth was growing underneath. Isaac smiled at the gap in the mirror.","questions":[{"question":"What did Isaac bite into?","choices":["an apple","a carrot","a sandwich","a cookie"],"answer":"an apple"},{"question":"What was growing under the baby tooth?","choices":["an adult tooth","a new gum","another baby tooth","a tiny bone"],"answer":"an adult tooth"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: When Isaac bit into an apple, his front tooth wiggled loose and came out. Focus on: a smiling boy with a missing front tooth. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Pumpkins grow on long, twisty vines. In spring, farmers plant pumpkin seeds. Yellow flowers bloom in summer, and small green pumpkins appear. By fall, most pumpkins have turned bright orange. People carve them, bake them into pies, and roast their seeds.","questions":[{"question":"When do farmers plant pumpkin seeds?","choices":["in spring","in fall","in winter","at night"],"answer":"in spring"},{"question":"What color are most pumpkins by fall?","choices":["orange","green","yellow","purple"],"answer":"orange"},{"question":"What do pumpkins grow on?","choices":["vines","trees","bushes","rocks"],"answer":"vines"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Pumpkins grow on long, twisty vines. Focus on: orange pumpkins on twisty vines. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."}],"2":[{"text":"In the early 1900s, city streets were becoming crowded with automobiles, horse-drawn wagons, bicycles, and people on foot. Early traffic signals had only two commands, stop and go, and they switched with no warning, which led to collisions at busy intersections. Garrett Morgan, an inventor in Cleveland, Ohio, witnessed a serious crash and decided to address the problem. In 1923 he received a patent for a signal that added a third position, which halted traffic in every direction for a moment before the signal changed. That brief pause gave drivers time to react. Today's yellow light serves a similar purpose: it warns drivers that the signal is about to change.","questions":[{"question":"In the passage, the word witnessed means?","choices":["saw with his own eyes","read about in a paper","caused by his own car","heard about from a friend"],"answer":"saw with his own eyes"},{"question":"Why was the third position in Morgan's signal helpful?","choices":["It gave drivers time to react before the signal changed","It made the signal easier to see at night","It let people on foot cross at any time","It allowed horses and cars to use separate lanes"],"answer":"It gave drivers time to react before the signal changed"},{"question":"Which modern signal serves a similar purpose to Morgan's third position?","choices":["the yellow light","the flashing green arrow","the walk sign","the red light"],"answer":"the yellow light"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: In the early 1900s, city streets were becoming crowded with automobiles, horse-drawn wagons, bicycles, and people on foot. Focus on: an early 1900s street intersection with a three-position traffic signal. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Periodical cicadas have one of the strangest life cycles in the insect world. After hatching, the young insects, called nymphs, burrow underground, where they feed on sap from tree roots. Depending on the type, they remain hidden for either 13 or 17 years. Then, in a single spring, millions of nymphs tunnel to the surface at once, climb nearby trees, and shed their skins to become winged adults. The males produce a loud, buzzing chorus to attract mates. Scientists think emerging in such enormous numbers helps the species survive: predators like birds can eat only a small fraction of them, so plenty remain to lay eggs for the next generation.","questions":[{"question":"In the passage, the word emerging means?","choices":["coming out into view","sleeping for a long time","flying south together","growing larger quickly"],"answer":"coming out into view"},{"question":"Why might it help cicadas to appear in huge numbers all at once?","choices":["Predators cannot eat them all, so many survive","Their loud songs scare away hungry birds","They can share food more easily in large groups","The trees grow more sap when many arrive"],"answer":"Predators cannot eat them all, so many survive"},{"question":"Where do cicada nymphs spend most of their lives?","choices":["underground, feeding on root sap","inside hollow tree branches","under rocks near streams","in nests high in the trees"],"answer":"underground, feeding on root sap"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Periodical cicadas have one of the strangest life cycles in the insect world. Focus on: cicadas climbing a tree and shedding their skins. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Seahorses are fish, even though they look nothing like most fish. They swim upright and steer with a small fin on their back, but they are poor swimmers. To keep from drifting away in ocean currents, a seahorse wraps its curled tail around seagrass or coral. Seahorses are also unusual parents. The female places her eggs into a pouch on the male's belly, and the male carries them until the babies are born. A single male can release hundreds of tiny seahorses at once.","questions":[{"question":"In the passage, the word drifting means?","choices":["being carried along slowly","diving down very deep","hiding under the sandy floor","eating small plants"],"answer":"being carried along slowly"},{"question":"What is the main idea of the passage?","choices":["Seahorses are unusual fish in how they swim and raise young","Seahorses are the fastest swimmers on a coral reef","Seahorses spend most of their lives buried in sand","Seahorses are not really fish but a kind of horse"],"answer":"Seahorses are unusual fish in how they swim and raise young"},{"question":"Why does a seahorse wrap its tail around seagrass?","choices":["to keep from drifting away","to catch small fish","to build a nest for its eggs","to sleep upside down"],"answer":"to keep from drifting away"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Seahorses are fish, even though they look nothing like most fish. Focus on: a seahorse with its tail wrapped around seagrass. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"In 1872, Congress set aside a vast area of land in the West as Yellowstone, the first national park in the United States and widely considered the first in the world. Explorers had returned with stories of boiling springs, bubbling mud pots, and geysers that shot water high into the air. Many people back east did not believe these reports until they saw paintings and photographs. Leaders decided the land was too remarkable to be sold or built upon, so it was protected for everyone to enjoy. Today, millions of visitors come each year, and the national park system includes more than sixty parks.","questions":[{"question":"In the passage, the word remarkable means?","choices":["worth noticing because it is unusual","difficult to travel across","owned by a single family","too dangerous for families to visit alone"],"answer":"worth noticing because it is unusual"},{"question":"Why did paintings and photographs matter to Yellowstone's story?","choices":["They helped convince doubtful people the reports were true","They were sold to raise money for building roads","They showed where gold could be found in the park","They were used to draw the park's first maps"],"answer":"They helped convince doubtful people the reports were true"},{"question":"What was Yellowstone the first of in the United States?","choices":["national park","state forest","public zoo","city playground"],"answer":"national park"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: In 1872, Congress set aside a vast area of land in the West as Yellowstone, the first national park in the United States and widely considered the first in the world. Focus on: Yellowstone geysers and hot springs. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Dev's robotics team had spent three weeks building a robot to sort colored blocks. At the regional contest, the robot rolled forward, paused, and dropped every block on the floor. The team was crushed. On the bus ride home, nobody spoke. The next morning, though, Dev pulled out the notebook where they had recorded every test. He noticed that the robot had always been tested under the classroom's dim lights, while the contest hall was flooded with bright light. The color sensor had been confused. The team adjusted the sensor's settings and tested it in sunlight, in shade, and under lamps. At the next contest, the robot sorted every block perfectly.","questions":[{"question":"In the passage, the word crushed means?","choices":["very disappointed","squeezed until flat","proud and happy","completely lost"],"answer":"very disappointed"},{"question":"What caused the robot to fail at the first contest?","choices":["The bright lights confused its color sensor","Its battery ran out during the contest","A wheel fell off on the way to the hall","The judges used blocks that were too heavy for it to lift"],"answer":"The bright lights confused its color sensor"},{"question":"What lesson does the story best show?","choices":["Careful records can help you learn from a failure","Robots should only be used in dark rooms","It is best to quit after losing a contest","Winning matters more than teamwork"],"answer":"Careful records can help you learn from a failure"}],"photo":"images/flashcards/robot.jpg"},{"text":"Beavers are sometimes called nature's engineers. Using their strong, orange front teeth, which never stop growing, they cut down trees and drag branches into streams. They pack the branches with mud and stones to build dams. The dam slows the water and creates a calm pond, where the beavers build a lodge with an underwater entrance that keeps predators out. These ponds do more than shelter beavers. They provide homes for fish, frogs, ducks, and insects, and they help store water during dry seasons.","questions":[{"question":"In the passage, the word shelter means?","choices":["protect and give a safe place to","feed with fresh plants","wash away quickly","carry downstream"],"answer":"protect and give a safe place to"},{"question":"Which sentence best states the main idea?","choices":["Beaver dams change streams in ways that help many living things","Beavers are dangerous to fish and frogs that live in streams","Beavers' teeth stop growing after they build their very first dam","Beavers build lodges only on dry land far from water"],"answer":"Beaver dams change streams in ways that help many living things"},{"question":"How does the underwater entrance help beavers?","choices":["It keeps predators out of the lodge","It lets them catch fish more easily","It keeps the pond from freezing","It helps them store branches"],"answer":"It keeps predators out of the lodge"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Beavers are sometimes called nature's engineers. Focus on: a beaver dam and lodge in a pond. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"When a phone shows your location on a map, it is relying on satellites orbiting thousands of miles above Earth. Each satellite constantly sends out signals that include the exact time the signal was sent. A receiver on the ground picks up signals from at least four satellites and calculates how long each one took to arrive. Because the signals travel at a known speed, the receiver can figure out its distance from each satellite and pinpoint where it is. The system depends on extremely precise clocks; an error of just one millionth of a second could place you hundreds of feet away.","questions":[{"question":"In the passage, the word pinpoint means?","choices":["find the exact position of","draw a picture of","send a message to","make something smaller and sharper"],"answer":"find the exact position of"},{"question":"Why does the system need extremely precise clocks?","choices":["Tiny timing errors can cause big location errors","Satellites must know when to switch off at night","Phones use the clocks to set their alarms","The clocks keep the satellites from falling"],"answer":"Tiny timing errors can cause big location errors"},{"question":"How many satellites must a receiver hear from?","choices":["at least four","exactly one","at least ten","no more than two"],"answer":"at least four"}],"photo":"images/flashcards/map.jpg"},{"text":"Every December, Abuela Rosa invites the whole family to her kitchen to make tamales. This year, Sofia was finally old enough to help. Abuela showed her how to spread a thin layer of masa, a soft corn dough, across a soaked corn husk. Sofia's first tamales were lumpy and lopsided, and a few fell apart in the steamer. Abuela only laughed and said her own first tamales had looked even worse. By the end of the afternoon, Sofia's tamales were neat and tidy, and she stacked them proudly on the platter beside Abuela's.","questions":[{"question":"In the passage, the word lopsided means?","choices":["uneven, with one side lower or bigger","cooked for too long","sweet and full of flavor","wrapped very tightly with extra string"],"answer":"uneven, with one side lower or bigger"},{"question":"Why did Abuela tell Sofia about her own first tamales?","choices":["to encourage Sofia not to give up","to explain why the steamer broke","to show that she had always been the better cook","to tell her to stop helping"],"answer":"to encourage Sofia not to give up"},{"question":"According to the passage, what is masa?","choices":["a soft corn dough","a soaked corn husk","a kind of steamer","a spicy red sauce"],"answer":"a soft corn dough"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Every December, Abuela Rosa invites the whole family to her kitchen to make tamales. Focus on: a grandmother and girl making tamales. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Have you ever touched a doorknob after shuffling across a carpet and felt a tiny zap? That shock is static electricity. Everything is made of atoms, which contain particles with electric charges. When two materials rub together, tiny particles called electrons can move from one material to the other. Your body builds up extra charge as you walk. When your finger gets close to a metal doorknob, the extra electrons suddenly jump across the gap, and you feel a spark. Static shocks happen more often in winter because dry air allows charge to build up instead of leaking away.","questions":[{"question":"In the passage, the word shuffling means?","choices":["walking while dragging your feet","running as fast as possible","jumping up and down on both feet","standing perfectly still"],"answer":"walking while dragging your feet"},{"question":"Why do static shocks happen more often in winter?","choices":["Dry air lets charge build up","Cold doorknobs hold more electricity","People wear heavier shoes in winter","Carpets are cleaned less often"],"answer":"Dry air lets charge build up"},{"question":"What jumps from your finger to the doorknob?","choices":["extra electrons","tiny drops of water","bits of carpet","specks of dust"],"answer":"extra electrons"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Have you ever touched a doorknob after shuffling across a carpet and felt a tiny zap? That shock is static electricity. Focus on: a child touching a doorknob with a tiny static spark. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"In the late 1800s, farmers across the American South grew cotton year after year in the same fields. Cotton drained nutrients from the soil, and harvests grew smaller and smaller. George Washington Carver, a scientist and teacher at the Tuskegee Institute in Alabama, urged farmers to rotate their crops, planting peanuts in some seasons instead of cotton. Peanuts, like beans, add nitrogen back into the soil, which helped restore the fields. To make sure farmers could earn money from their new crop, Carver developed hundreds of uses for peanuts, from foods to dyes. Although many people believe he invented peanut butter, he did not; his greatest contribution was helping farmers protect their land.","questions":[{"question":"In the passage, the word restore means?","choices":["bring back to a good condition","sell at a higher price","cover with a thin layer","dig up and carry away to another field"],"answer":"bring back to a good condition"},{"question":"What was Carver's most important contribution, according to the passage?","choices":["helping farmers protect and improve their soil","inventing peanut butter and selling it to American families","building the Tuskegee Institute in Alabama","growing more cotton than any other farmer"],"answer":"helping farmers protect and improve their soil"},{"question":"Why did cotton harvests grow smaller over time?","choices":["Cotton drained nutrients from the soil","There was too much rain each year","Insects ate the peanuts nearby","Farmers planted too few seeds"],"answer":"Cotton drained nutrients from the soil"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: In the late 1800s, farmers across the American South grew cotton year after year in the same fields. Focus on: peanut plants growing in a farm field. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"When the Parks' beagle, Pepper, slipped out of the backyard gate, ten-year-old June felt panic rising in her chest. Instead of running around the block blindly, she took a breath and made a plan. She printed a flyer with Pepper's photo and her family's phone number, and her neighbors helped tape copies to lampposts. Mr. Okafor, who owned the corner bakery, posted one in his window. That evening the phone rang: a jogger had spotted Pepper napping on the bakery's back step, probably drawn by the smell of fresh bread.","questions":[{"question":"In the passage, the word blindly means?","choices":["without a plan or careful thought","with her eyes tightly closed","very quickly and loudly","while carrying a bright flashlight in the dark"],"answer":"without a plan or careful thought"},{"question":"Why was Pepper probably at the bakery?","choices":["The smell of fresh bread attracted her","Mr. Okafor had taken her there","She was following the jogger","June had left her there earlier"],"answer":"The smell of fresh bread attracted her"},{"question":"What did June do first after Pepper ran away?","choices":["She took a breath and made a plan","She ran around the block","She called the police","She waited beside the open gate all night"],"answer":"She took a breath and made a plan"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: When the Parks' beagle, Pepper, slipped out of the backyard gate, ten-year-old June felt panic rising in her chest. Focus on: a beagle napping on a bakery's back step. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"For seventy-six years after its discovery in 1930, Pluto was known as the ninth planet. Then astronomers began finding other icy objects in the same distant region, some nearly as large as Pluto. In 2006, scientists at the International Astronomical Union agreed on a definition: a planet must orbit the sun, be massive enough to become round, and clear other objects from its orbital path. Pluto meets the first two rules but not the third, so it was reclassified as a dwarf planet. In 2015, the New Horizons spacecraft flew past Pluto and revealed mountains of ice and a giant heart-shaped plain.","questions":[{"question":"In the passage, the word reclassified means?","choices":["placed into a different group","removed from the sky","made larger and brighter","discovered a second time"],"answer":"placed into a different group"},{"question":"Why is Pluto no longer called a planet?","choices":["It has not cleared other objects from its path","It is not round like the other planets","It does not orbit the sun","It is too far away to study"],"answer":"It has not cleared other objects from its path"},{"question":"What did New Horizons find on Pluto?","choices":["a heart-shaped plain","oceans of liquid water","forests of tall trees","a ring like Saturn's"],"answer":"a heart-shaped plain"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: For seventy-six years after its discovery in 1930, Pluto was known as the ninth planet. Focus on: Pluto with its heart-shaped plain. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Sand dunes are hills of sand shaped by the wind. When wind blows across a desert or beach, it lifts loose grains and bounces them along the ground. Where something blocks the wind, such as a rock or a bush, grains pile up. Over time, the pile grows into a dune with a gentle slope on the side facing the wind and a steep slope on the sheltered side. Because wind keeps moving the grains, many dunes slowly creep forward, sometimes several feet each year. Some dunes even make a low humming or booming sound when sand slides down their slopes.","questions":[{"question":"In the passage, the word creep means?","choices":["move slowly","jump high","disappear suddenly","shine brightly"],"answer":"move slowly"},{"question":"Which sentence best summarizes the passage?","choices":["Wind builds sand dunes and keeps them slowly moving","Sand dunes form only on the beaches of oceans","Rocks and bushes are made from piles of sand","Dunes stay in the same place for thousands of years"],"answer":"Wind builds sand dunes and keeps them slowly moving"},{"question":"What can make sand begin to pile up?","choices":["something that blocks the wind","a heavy rainstorm","a sudden earthquake","waves from the ocean"],"answer":"something that blocks the wind"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Sand dunes are hills of sand shaped by the wind. Focus on: wind blowing sand over desert dunes. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"During recess, Elijah accidentally kicked his soccer ball into the window of the art room, leaving a long crack across the glass. Nobody else had seen it happen. For the rest of the afternoon, he felt a heavy knot in his stomach and could barely focus on his spelling words. Finally, he walked to the principal's office and explained what had happened. Ms. Rivera thanked him for his honesty and asked him to help the custodian measure the window for a new pane. Walking home, Elijah noticed that the knot in his stomach was gone.","questions":[{"question":"In the passage, the word honesty means?","choices":["telling the truth","playing a sport well","being very fast","feeling hungry"],"answer":"telling the truth"},{"question":"Why did the knot in Elijah's stomach go away?","choices":["He stopped worrying after telling the truth","He ate a big snack after school","The custodian told him the window was never really cracked","He won his soccer game at recess"],"answer":"He stopped worrying after telling the truth"},{"question":"What did Ms. Rivera ask Elijah to do?","choices":["help measure the window","clean the art room","write a letter","stay inside at recess"],"answer":"help measure the window"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: During recess, Elijah accidentally kicked his soccer ball into the window of the art room, leaving a long crack across the glass. Focus on: a boy talking honestly with a school principal. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Mangroves are trees that grow along tropical coastlines, where few other trees can survive. Their roots arch above the muddy ground like stilts, holding the trees steady as tides rise and fall twice a day. Mangroves can tolerate salt water; some filter salt out through their roots, while others push extra salt out through their leaves. The tangled roots also create a nursery for young fish, crabs, and shrimp, which hide among them from larger predators. During storms, mangrove forests act as a natural barrier, slowing waves and protecting the coast.","questions":[{"question":"In the passage, the word tolerate means?","choices":["survive in spite of","turn into","run away from","grow much taller than"],"answer":"survive in spite of"},{"question":"What is the main idea of the passage?","choices":["Mangroves are specially suited to coasts and help protect them","Mangroves grow best in cold, dry mountain regions","Mangroves are harmful to fish and other sea animals","Mangrove roots grow deep underground where no one can see them"],"answer":"Mangroves are specially suited to coasts and help protect them"},{"question":"How do mangrove forests help during storms?","choices":["They slow waves and protect the coast","They soak up all the rainwater","They make the wind stop blowing","They warn animals to swim away"],"answer":"They slow waves and protect the coast"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Mangroves are trees that grow along tropical coastlines, where few other trees can survive. Focus on: mangrove trees with stilt roots along a coast. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Hailstones are balls of ice that fall from powerful thunderstorms, usually in spring and summer. Inside a storm cloud, strong upward winds called updrafts carry raindrops high into air that is far below freezing. The drops freeze into small pellets of ice. As they fall, they collect a coating of water, then get swept upward again, where that water freezes into a new layer. A hailstone may travel up and down many times, growing like an onion with rings. When it becomes too heavy for the updraft to hold, it finally falls to the ground.","questions":[{"question":"In the passage, the word coating means?","choices":["a thin layer covering something","a warm and heavy winter jacket","a loud clap of thunder in the cloud","a hole in the middle"],"answer":"a thin layer covering something"},{"question":"Why does a hailstone finally fall to the ground?","choices":["It gets too heavy for the updraft to hold","The cloud runs out of water","The sun melts the updraft","The storm turns into snow"],"answer":"It gets too heavy for the updraft to hold"},{"question":"Why does the passage compare a hailstone to an onion?","choices":["Both are made of many layers","Both grow underground","Both have a strong smell","Both can be found in a kitchen freezer"],"answer":"Both are made of many layers"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Hailstones are balls of ice that fall from powerful thunderstorms, usually in spring and summer. Focus on: layered hailstones falling from a storm cloud. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Before 1825, moving goods from the Great Lakes to the Atlantic coast meant long, bumpy trips by wagon over rough roads. The Erie Canal changed that. Stretching about 363 miles across New York, from the Hudson River to Lake Erie, the human-made waterway allowed flat boats to carry heavy loads cheaply. Mules walked along towpaths beside the canal, pulling the boats with ropes. Because the land rose and fell, workers built locks, chambers that raised or lowered boats like water elevators. The cost of shipping dropped sharply, and New York City grew into the nation's busiest port.","questions":[{"question":"In the passage, the word chambers means?","choices":["enclosed spaces or rooms","tall wooden bridges","large cargo boats","teams of hardworking mules"],"answer":"enclosed spaces or rooms"},{"question":"What was one important effect of the Erie Canal?","choices":["Shipping goods became much cheaper","Wagons became more popular than boats","Lake Erie dried up completely","Mules were no longer needed"],"answer":"Shipping goods became much cheaper"},{"question":"What job did the mules do?","choices":["pulled the boats with ropes","dug the canal","carried mail","built the locks"],"answer":"pulled the boats with ropes"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Before 1825, moving goods from the Great Lakes to the Atlantic coast meant long, bumpy trips by wagon over rough roads. Focus on: a mule pulling a canal boat along a towpath. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"For the science fair, Nadia wondered whether plants grow better with music. She planted six bean seeds in identical cups with the same soil. Three cups sat near a speaker that played soft music each afternoon, and three sat in a quiet room. She gave every cup the same amount of water and sunlight. After three weeks, the plants in both groups were nearly the same height. Nadia was surprised, but her teacher pointed out that a result that disproves a guess is still valuable. Nadia's poster explained what she learned and suggested testing louder music next time.","questions":[{"question":"In the passage, the word identical means?","choices":["exactly alike","very large","brightly colored","full of holes"],"answer":"exactly alike"},{"question":"Why did Nadia give every cup the same water and sunlight?","choices":["so only the music would be different","so the plants would grow very tall","so she could use less water","so the speaker on the table would never get wet"],"answer":"so only the music would be different"},{"question":"What did the teacher say about Nadia's result?","choices":["It was still valuable","It was a failure","It must be wrong","It was too small"],"answer":"It was still valuable"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: For the science fair, Nadia wondered whether plants grow better with music. Focus on: bean plants in identical cups near a music speaker. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Look closely at almost any package in a grocery store and you will find a barcode, a pattern of black bars and white spaces of different widths. Each pattern stands for a number that identifies the product. When a cashier passes the package over a scanner, a beam of light sweeps across the code. Black bars absorb the light while white spaces reflect it, and a sensor reads the pattern of reflections. A computer instantly looks up the number to find the item's name and price. The first product scanned this way, in 1974, was a pack of chewing gum.","questions":[{"question":"In the passage, the word absorb means?","choices":["soak up","bounce back","break apart","make louder"],"answer":"soak up"},{"question":"What does the computer do after the scanner reads the code?","choices":["looks up the item's name and price","prints a new barcode","turns off the beam of light","cleans the scanner glass"],"answer":"looks up the item's name and price"},{"question":"What is the passage mostly about?","choices":["how barcodes and scanners work","why chewing gum was invented","how grocery stores choose prices","why some packages are black and white"],"answer":"how barcodes and scanners work"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Look closely at almost any package in a grocery store and you will find a barcode, a pattern of black bars and white spaces of different widths. Focus on: a barcode being scanned at a grocery checkout. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Lena and Maya had planned their bake sale for weeks, but on the morning of the sale they argued about everything: the prices, the sign, even which cookies to bake. Maya stomped off, and Lena sat alone behind the table. After an hour without a single customer, Lena realized she missed her friend more than she cared about the cookies. She walked to Maya's house and apologized. Maya admitted she had been stubborn too. Together they painted a bright new sign, and by evening they had sold every last cookie.","questions":[{"question":"In the passage, the word stubborn means?","choices":["unwilling to change your mind","very tired and sleepy","very good at baking cookies and bread","quiet and shy"],"answer":"unwilling to change your mind"},{"question":"What is the main lesson of the story?","choices":["Friendship matters more than small disagreements","Bake sales only work with a bright sign","It is always better to work alone than with others","Customers care most about the price of cookies"],"answer":"Friendship matters more than small disagreements"},{"question":"Why did Lena go to Maya's house?","choices":["She missed her friend and wanted to make up","She needed more cookies to sell","She wanted to ask about the prices","She forgot the sign there"],"answer":"She missed her friend and wanted to make up"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Lena and Maya had planned their bake sale for weeks, but on the morning of the sale they argued about everything: the prices, the sign, even which cookies to bake. Focus on: two friends at a bake sale table with cookies. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Every time you breathe in, air travels down your windpipe and into your lungs, where it flows through smaller and smaller tubes. At the ends of these tubes are millions of tiny air sacs called alveoli. Each sac is wrapped in tiny blood vessels. Oxygen passes from the air sacs into the blood, which carries it to every part of your body. At the same time, carbon dioxide, a waste gas, moves from the blood into the sacs so you can breathe it out. Exercise strengthens the muscles that help you breathe, which is one reason athletes can run long distances without tiring as quickly.","questions":[{"question":"In the passage, the word waste means?","choices":["something the body does not need","something very valuable","a kind of food","a large tube that carries fresh blood"],"answer":"something the body does not need"},{"question":"What moves from the blood into the air sacs?","choices":["carbon dioxide","fresh oxygen gas","drops of water","bits of food"],"answer":"carbon dioxide"},{"question":"Why might athletes run long distances without tiring as quickly?","choices":["Exercise has strengthened their breathing muscles","They have more air sacs than other people","Their windpipes are much shorter","They breathe only carbon dioxide"],"answer":"Exercise has strengthened their breathing muscles"}]},{"text":"In the 1700s, books in the American colonies were expensive, and most had to be shipped from England. In 1731, Benjamin Franklin and a group of friends in Philadelphia came up with a clever solution. Each member paid a fee to join, and the money was pooled to buy books that everyone could borrow. This group, called the Library Company of Philadelphia, became one of the first lending libraries in America. The idea spread to other towns. Today, public libraries across the country lend books, movies, and computers for free, carrying on the idea that knowledge should be shared.","questions":[{"question":"In the passage, the word pooled means?","choices":["combined into one shared amount","poured into water","saved by one person in a secret box","spent on swimming"],"answer":"combined into one shared amount"},{"question":"What is the main idea of the passage?","choices":["Sharing resources helped make books available to more people","Benjamin Franklin wrote most of the books in early libraries","Books were cheaper in the colonies than in England","Libraries today only lend books to paying members"],"answer":"Sharing resources helped make books available to more people"},{"question":"Why was it hard to get books in the colonies?","choices":["They were expensive and shipped from England","There were no printers in the world","People were not allowed to read","Books were only written in French"],"answer":"They were expensive and shipped from England"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: In the 1700s, books in the American colonies were expensive, and most had to be shipped from England. Focus on: colonial readers borrowing books from an early library. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Snow leopards live in the rugged mountains of Central Asia, at heights where the air is thin and temperatures drop far below freezing. Their thick, smoky-gray fur, spotted with dark rosettes, keeps them warm and helps them blend into rocky slopes. Wide, furry paws act like natural snowshoes, spreading their weight so they do not sink into deep snow. A snow leopard's long tail, nearly as long as its body, helps it balance on narrow ledges and can be wrapped around its face like a scarf while it sleeps. Because they are so well hidden, people sometimes call them the ghosts of the mountains.","questions":[{"question":"In the passage, the word rugged means?","choices":["rough and uneven","soft and flat","warm and sunny","crowded and busy"],"answer":"rough and uneven"},{"question":"Why are snow leopards called the ghosts of the mountains?","choices":["They are very hard to see","They only come out at night","They make spooky sounds","They are white like ghosts"],"answer":"They are very hard to see"},{"question":"How do wide paws help snow leopards?","choices":["They keep them from sinking into snow","They help them swim across icy mountain rivers","They help them dig deep burrows","They help them climb tall trees"],"answer":"They keep them from sinking into snow"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Snow leopards live in the rugged mountains of Central Asia, at heights where the air is thin and temperatures drop far below freezing. Focus on: a snow leopard on a rocky mountain ledge. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Tariq volunteered to write an article for the school newspaper about the cafeteria staff. He assumed the job was simple: serve lunch and clean up. But when he interviewed Ms. Delgado, the head cook, he learned that her team arrived at six every morning, prepared meals for four hundred students, and adjusted recipes for children with food allergies. Tariq's article, titled The Lunch Heroes, surprised many readers. The next week, several classes made thank-you cards for the cafeteria team, and Ms. Delgado hung them all on the kitchen wall.","questions":[{"question":"In the passage, the word assumed means?","choices":["believed without knowing for sure","wrote down carefully","asked a question","cooked a meal"],"answer":"believed without knowing for sure"},{"question":"Why did Tariq's article most likely surprise many readers?","choices":["It showed how hard the staff really worked","They believed the school did not have a cafeteria","They did not know Tariq could write","They thought lunch was served at six"],"answer":"It showed how hard the staff really worked"},{"question":"How did classes respond to the article?","choices":["They made thank-you cards","They cooked lunch","They wrote new recipes","They visited a restaurant"],"answer":"They made thank-you cards"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Tariq volunteered to write an article for the school newspaper about the cafeteria staff. Focus on: a student interviewing a school cafeteria cook. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."},{"text":"Limestone caves form over thousands of years. Rainwater picks up a gas called carbon dioxide from the air and soil, which turns the water slightly acidic. As this water seeps into cracks in limestone rock, it slowly dissolves the rock, widening the cracks into tunnels and rooms. Inside the cave, water dripping from the ceiling leaves behind tiny bits of minerals. Over centuries, these deposits build icicle-shaped stalactites that hang down and stalagmites that rise up from the floor. When the two meet, they form a column.","questions":[{"question":"In the passage, the word seeps means?","choices":["flows slowly through small openings","jumps quickly into the air","freezes into solid sheets of ice overnight","stays still in one place"],"answer":"flows slowly through small openings"},{"question":"What forms when a stalactite and a stalagmite meet?","choices":["a column","a tunnel","a crack","a waterfall"],"answer":"a column"},{"question":"What causes the limestone to dissolve?","choices":["slightly acidic rainwater","strong winds","animals digging","heat from the sun"],"answer":"slightly acidic rainwater"}],"image_prompt":"A warm, simple flat-style children's-book illustration for a kids' reading app. Scene: Limestone caves form over thousands of years. Focus on: stalactites and stalagmites inside a limestone cave. Bright friendly colors, soft rounded shapes, no text or letters anywhere in the image, square 1:1 aspect ratio, cheerful and inviting for young readers."}]},"synonyms":{"easy":{"chuckle":"laugh","rush":"dash","soggy":"soaked","grab":"snatch","plump":"chubby","sturdy":"solid","cozy":"snug","stroll":"wander"},"hard":{"tenacious":"persistent","lavish":"extravagant","ominous":"threatening","placid":"peaceful","feasible":"possible","vibrant":"lively","trivial":"unimportant"}},"antonyms":{"easy":{"crooked":"straight","rough":"smooth","cheap":"expensive","clumsy":"graceful","busy":"idle","together":"apart","dim":"bright","forward":"backward"},"hard":{"reckless":"cautious","obscure":"famous","triumph":"defeat","affluent":"impoverished","rigid":"flexible","sparse":"dense","mandatory":"optional"}},"rhymes":{"easy":[["sock","rock","dock","knock"],["map","cap","tap","nap","lap"],["bun","fun","run","sun"],["bed","fed","sled","shed"]],"hard":[["shiver","river","quiver","deliver","sliver"],["tumble","rumble","grumble","mumble","humble"],["bubble","double","stubble","rubble"],["pocket","socket","locket","docket"]]},"analogies":[["feather","bird","scale","fish"],["glove","hand","hat","head"],["chef","kitchen","pilot","cockpit"],["cow","milk","hen","egg"],["pages","book","keys","piano"],["calf","cow","lamb","sheep"],["paw","dog","hoof","horse"],["thirsty","drink","tired","sleep"]]}];
